-- ------------------------------------------------------------------
-- wms_serial_fact_check() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
DECLARE valid BOOLEAN;
BEGIN
 CASE TG_TABLE_NAME
 WHEN 'wms_serial_modes' THEN SELECT wms_serial_mode_original(m) AND (NOT m.controlled OR EXISTS(SELECT 1 FROM wms_serial_heads h WHERE h.tenant=m.tenant AND h.sku=m.sku AND wms_serial_head_bound(h))) INTO valid FROM wms_serial_modes m WHERE tenant=NEW.tenant AND sku=NEW.sku;
 WHEN 'wms_serial_batches' THEN SELECT wms_serial_batch_original(b) AND EXISTS(SELECT 1 FROM wms_serial_heads h WHERE h.tenant=b.tenant AND h.sku=b.sku AND wms_serial_head_bound(h)) INTO valid FROM wms_serial_batches b WHERE tenant=NEW.tenant AND sku=NEW.sku AND version=NEW.version;
 WHEN 'wms_serial_steps' THEN SELECT wms_serial_step_bound(s) AND EXISTS(SELECT 1 FROM wms_serial_units u WHERE u.tenant=s.tenant AND u.sku=s.sku AND u.serial=s.serial AND wms_serial_unit_bound(u)) INTO valid FROM wms_serial_steps s WHERE tenant=NEW.tenant AND sku=NEW.sku AND serial=NEW.serial AND revision=NEW.revision;
 WHEN 'wms_serial_observations' THEN SELECT wms_serial_observation_bound(o) INTO valid FROM wms_serial_observations o WHERE tenant=NEW.tenant AND warehouse_id=NEW.warehouse_id AND event_id=NEW.event_id AND ordinal=NEW.ordinal;
 WHEN 'wms_serial_units' THEN SELECT wms_serial_unit_bound(u) INTO valid FROM wms_serial_units u WHERE tenant=NEW.tenant AND sku=NEW.sku AND serial=NEW.serial;
 WHEN 'wms_serial_heads' THEN SELECT wms_serial_head_bound(h) INTO valid FROM wms_serial_heads h WHERE tenant=NEW.tenant AND sku=NEW.sku;
 ELSE valid=false;
 END CASE;
 IF valid IS DISTINCT FROM true THEN RAISE EXCEPTION 'Original serial source, revision chain or current projection disagrees' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END 

-- ------------------------------------------------------------------
-- wms_serial_head_bound(h wms_serial_heads) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT EXISTS(SELECT 1 FROM wms_serial_modes m WHERE m.tenant=h.tenant AND m.sku=h.sku AND m.controlled)
 AND ((h.version=0 AND h.last_event_id IS NULL AND NOT EXISTS(SELECT 1 FROM wms_serial_batches b WHERE b.tenant=h.tenant AND b.sku=h.sku))
 OR (EXISTS(SELECT 1 FROM wms_serial_batches b WHERE b.tenant=h.tenant AND b.sku=h.sku AND b.version=h.version AND b.event_id=h.last_event_id AND wms_serial_batch_original(b))
 AND NOT EXISTS(SELECT 1 FROM wms_serial_batches b WHERE b.tenant=h.tenant AND b.sku=h.sku AND b.version>h.version)));

-- ------------------------------------------------------------------
-- wms_serial_head_identity() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
BEGIN
 IF TG_OP='DELETE' OR (NEW.tenant,NEW.sku) IS DISTINCT FROM (OLD.tenant,OLD.sku)
  OR NEW.version<>OLD.version+1 OR NEW.last_event_id IS NULL OR NEW.last_event_id IS NOT DISTINCT FROM OLD.last_event_id THEN
  RAISE EXCEPTION 'Serial review heads advance once per original SKU event' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_serial_inputs_match_command(t text, w text, c jsonb, inputs jsonb) RETURNS boolean
-- LANGUAGE plpgsql STABLE
DECLARE n BIGINT; target_rows JSONB;
BEGIN
 IF jsonb_typeof(inputs) IS DISTINCT FROM 'array' OR jsonb_array_length(inputs)>100 THEN RETURN false; END IF;
 SELECT COALESCE(jsonb_agg(to_jsonb(q)),'[]'::jsonb) INTO target_rows FROM wms_serial_targets(t,w,c) q;
 -- Each original target is one declaration. A duplicated command line must
 -- not reuse a single observation merely because both entries name one SKU.
 IF EXISTS(SELECT 1 FROM jsonb_to_recordset(target_rows) AS q(target JSONB,sku TEXT,each_quantity BIGINT,allow_zero BOOLEAN) GROUP BY q.target HAVING count(*)>1) THEN RETURN false; END IF;
 -- Validate shapes before expanding any member arrays. CASE keeps malformed
 -- JSON from reaching array operations. Count the bounded groups before labels.
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(inputs) AS entry(doc) WHERE
  CASE WHEN jsonb_typeof(doc) IS DISTINCT FROM 'object' THEN true
   WHEN NOT doc ?& ARRAY['target','sku','serials'] OR doc-ARRAY['target','sku','serials']<>'{}'::jsonb
    OR jsonb_typeof(doc->'target') IS DISTINCT FROM 'array'
    OR jsonb_typeof(doc->'sku') IS DISTINCT FROM 'string'
    OR jsonb_typeof(doc->'serials') IS DISTINCT FROM 'array' THEN true
   ELSE jsonb_array_length(doc->'target')>3 OR NOT wms_serial_text(doc->>'sku') END
 ) THEN RETURN false; END IF;
 SELECT COALESCE(sum(jsonb_array_length(doc->'serials')),0) INTO n FROM jsonb_array_elements(inputs) AS entry(doc);
 IF n>10000 OR EXISTS(SELECT 1 FROM jsonb_array_elements(inputs) AS entry(doc)
  CROSS JOIN LATERAL jsonb_array_elements(doc->'target') AS member(value)
  WHERE jsonb_typeof(value) IS DISTINCT FROM 'string' OR NOT wms_serial_text(value#>>'{}'))
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(inputs) AS entry(doc)
  CROSS JOIN LATERAL jsonb_array_elements(doc->'serials') AS member(value)
  WHERE jsonb_typeof(value) IS DISTINCT FROM 'string' OR NOT wms_serial_text(value#>>'{}')) THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(inputs) AS entry(doc) GROUP BY entry.doc->'target' HAVING count(*)>1)
  OR EXISTS(SELECT 1 FROM jsonb_array_elements(inputs) AS entry(doc) CROSS JOIN LATERAL jsonb_array_elements(entry.doc->'serials') AS unit(label) GROUP BY entry.doc->>'sku',unit.label HAVING count(*)>1) THEN RETURN false; END IF;
 -- Resolve mode/product membership once and compare complete target sets.
 -- Materialized CTEs are statement-local computations under the same STABLE
 -- snapshot, so no saved validity flag can outlive its source snapshot.
 RETURN (
  WITH targets AS MATERIALIZED (
   SELECT q.*,EXISTS(SELECT 1 FROM wms_products p WHERE p.tenant=t AND p.warehouse_id=w
    AND p.sku=q.sku AND p.data->'serial_controlled'='true'::jsonb) AS product_valid
   FROM jsonb_to_recordset(target_rows) AS q(target JSONB,sku TEXT,each_quantity BIGINT,allow_zero BOOLEAN)
   JOIN wms_serial_modes m ON m.tenant=t AND m.sku=q.sku AND m.controlled
  ), observed AS MATERIALIZED (
   SELECT entry.doc->'target' AS target,entry.doc->>'sku' AS sku,jsonb_array_length(entry.doc->'serials') AS quantity
   FROM jsonb_array_elements(inputs) AS entry(doc)
  )
  SELECT NOT EXISTS(
   SELECT 1 FROM observed i LEFT JOIN targets q ON q.target=i.target AND q.sku=i.sku
    AND q.each_quantity=i.quantity AND (q.each_quantity>0 OR q.allow_zero)
   WHERE q.sku IS NULL
  ) AND NOT EXISTS(
   SELECT 1 FROM targets q LEFT JOIN observed i ON i.target=q.target AND i.sku=q.sku
   WHERE NOT q.product_valid OR i.sku IS NULL
  )
 );
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END 

-- ------------------------------------------------------------------
-- wms_serial_mode_immutable() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
BEGIN
 IF TG_OP='DELETE' OR NEW IS DISTINCT FROM OLD THEN
  RAISE EXCEPTION 'Serial mode is chosen before stock and cannot reinterpret existing SKU identity' USING ERRCODE='23514';
 END IF;
 -- An exact no-op update is permitted solely to fence concurrent catalog
 -- creation under repeatable-read snapshots; business fields remain immutable.
 RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_serial_mode_original(m wms_serial_modes) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT COALESCE(NOT EXISTS(SELECT 1 FROM wms_products p WHERE p.tenant=m.tenant AND p.sku=m.sku
  AND COALESCE(p.data->'serial_controlled','false'::jsonb)<>to_jsonb(m.controlled))
 AND (NOT m.controlled OR EXISTS(SELECT 1 FROM wms_events e JOIN wms_commands c
  ON c.tenant=e.tenant AND c.warehouse_id=e.warehouse_id AND c.request_id=e.payload->>'request_id'
  WHERE e.id=m.source_event_id AND e.tenant=m.tenant AND e.warehouse_id=m.source_warehouse_id
  AND e.payload->>'id'=e.id AND e.payload->>'tenant'=m.tenant AND e.payload->>'warehouse_id'=m.source_warehouse_id
  AND e.payload->'version'=to_jsonb(e.version) AND e.payload->>'actor'=c.actor
  AND e.payload->>'type'='product.created' AND e.payload->'result'=c.result
  AND c.result=jsonb_build_object('entity_id',m.sku,'version',e.version,'type','product.created')
  AND e.payload->'command'->>'type'='create_product' AND e.payload->'command'->>'sku'=m.sku
  AND e.payload->'command'->'serial_controlled'='true'::jsonb
  AND EXISTS(SELECT 1 FROM wms_products p WHERE p.tenant=m.tenant AND p.warehouse_id=m.source_warehouse_id AND p.sku=m.sku))),false);

-- ------------------------------------------------------------------
-- wms_serial_modes_original_for_scope(t text, source_sku text) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT NOT EXISTS(
  SELECT 1 FROM wms_serial_modes m WHERE m.tenant=t AND m.controlled AND(source_sku IS NULL OR m.sku=source_sku)
   AND NOT(COALESCE(NOT EXISTS(SELECT 1 FROM wms_products p WHERE p.tenant=m.tenant AND p.sku=m.sku
  AND COALESCE(p.data->'serial_controlled','false'::jsonb)<>'true'::jsonb)
 AND (NOT m.controlled OR EXISTS(SELECT 1 FROM wms_events e JOIN wms_commands c
  ON c.tenant=e.tenant AND c.warehouse_id=e.warehouse_id AND c.request_id=e.payload->>'request_id'
  WHERE e.id=m.source_event_id AND e.tenant=m.tenant AND e.warehouse_id=m.source_warehouse_id
  AND e.payload->>'id'=e.id AND e.payload->>'tenant'=m.tenant AND e.payload->>'warehouse_id'=m.source_warehouse_id
  AND e.payload->'version'=to_jsonb(e.version) AND e.payload->>'actor'=c.actor
  AND e.payload->>'type'='product.created' AND e.payload->'result'=c.result
  AND c.result=jsonb_build_object('entity_id',m.sku,'version',e.version,'type','product.created')
  AND e.payload->'command'->>'type'='create_product' AND e.payload->'command'->>'sku'=m.sku
  AND e.payload->'command'->'serial_controlled'='true'::jsonb
  AND EXISTS(SELECT 1 FROM wms_products p WHERE p.tenant=m.tenant AND p.warehouse_id=m.source_warehouse_id AND p.sku=m.sku))),false))
 );

-- ------------------------------------------------------------------
-- wms_serial_observation_bound(o wms_serial_observations) RETURNS boolean
-- LANGUAGE plpgsql STABLE
DECLARE original_payload JSONB;
BEGIN
 SELECT payload||'{}'::jsonb INTO original_payload FROM wms_events WHERE id=o.event_id;
 IF NOT FOUND THEN RETURN false; END IF;
 RETURN (SELECT EXISTS(SELECT 1 FROM wms_events e JOIN wms_serial_batches b ON b.tenant=o.tenant AND b.sku=o.sku AND b.version=o.sku_version AND b.event_id=o.event_id AND b.warehouse_id=o.warehouse_id
 WHERE e.id=o.event_id AND e.tenant=o.tenant AND e.warehouse_id=o.warehouse_id AND wms_serial_batch_original(b)
 AND original_payload->'serial_inputs'->(o.ordinal-1)=jsonb_build_object('target',o.target,'sku',o.sku,'serials',o.serials)
 AND wms_serial_event_inputs_bound(o.tenant,o.warehouse_id,o.event_id)));
END 

-- ------------------------------------------------------------------
-- wms_serial_on_hand(w text, b text) RETURNS jsonb
-- LANGUAGE sql IMMUTABLE
 SELECT jsonb_build_object('status','on_hand','warehouse_id',w,'location',b);

-- ------------------------------------------------------------------
-- wms_serial_pending_guard() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
BEGIN
 IF TG_OP IN('UPDATE','TRUNCATE') OR pg_trigger_depth()<2 THEN
  RAISE EXCEPTION 'Serial pending checks are owned by custody constraints' USING ERRCODE='23514';
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_serial_place_references_valid(t text, s text, l text, p jsonb) RETURNS boolean
-- LANGUAGE plpgsql STABLE
DECLARE valid BOOLEAN; status TEXT=p->>'status';
BEGIN
 IF NOT wms_serial_place_valid(p) OR NOT EXISTS(SELECT 1 FROM wms_serial_modes WHERE tenant=t AND sku=s AND controlled) THEN RETURN false; END IF;
 IF status IN('on_hand','missing') THEN
  RETURN EXISTS(SELECT 1 FROM wms_products product JOIN wms_locations bin ON bin.tenant=product.tenant AND bin.warehouse_id=product.warehouse_id
   WHERE product.tenant=t AND product.sku=s AND product.warehouse_id=p->>'warehouse_id' AND product.data->'serial_controlled'='true'::jsonb
   AND bin.code=p->>'location' AND bin.kind IN('storage','receiving'));
 ELSIF status='staged' THEN
  SELECT EXISTS(SELECT 1 FROM wms_allocations a WHERE a.tenant=t AND a.warehouse_id=p->>'warehouse_id' AND a.order_id=p->>'order_id'
   AND a.line_id=p->>'line_id' AND a.location=p->>'allocation_location' AND a.sku=s AND a.lot=l AND a.picked>a.shipped) INTO valid;
  RETURN valid AND (p->'package_id'='null'::jsonb OR EXISTS(SELECT 1 FROM wms_package_lines line
   WHERE line.tenant=t AND line.warehouse_id=p->>'warehouse_id' AND line.package_id=p->>'package_id' AND line.order_id=p->>'order_id'
   AND line.line_id=p->>'line_id' AND line.location=p->>'allocation_location' AND line.sku=s AND line.lot=l
   AND NOT EXISTS(SELECT 1 FROM wms_package_closures c WHERE c.tenant=line.tenant AND c.warehouse_id=line.warehouse_id AND c.package_id=line.package_id)));
 ELSIF status='shipped' THEN
  SELECT EXISTS(SELECT 1 FROM wms_order_lines line WHERE line.tenant=t AND line.warehouse_id=p->>'warehouse_id' AND line.order_id=p->>'order_id' AND line.id=p->>'line_id' AND line.sku=s)
   AND (CASE WHEN p->'package_id'='null'::jsonb THEN EXISTS(SELECT 1 FROM wms_shipment_evidence h WHERE h.tenant=t AND h.warehouse_id=p->>'warehouse_id' AND h.order_id=p->>'order_id' AND h.source_kind='event' AND h.event_id=p->>'handoff_event_id')
    ELSE EXISTS(SELECT 1 FROM wms_package_lines line JOIN wms_package_closures c ON c.tenant=line.tenant AND c.warehouse_id=line.warehouse_id AND c.package_id=line.package_id
     WHERE line.tenant=t AND line.warehouse_id=p->>'warehouse_id' AND line.package_id=p->>'package_id' AND line.order_id=p->>'order_id'
     AND line.line_id=p->>'line_id' AND line.sku=s AND line.lot=l AND c.kind='handed_off' AND c.event_id=p->>'handoff_event_id') END) INTO valid;
  RETURN valid AND (p->'return_receipt_id'='null'::jsonb OR EXISTS(SELECT 1 FROM wms_return_lines r JOIN wms_receipts receipt
   ON receipt.tenant=r.tenant AND receipt.warehouse_id=r.warehouse_id AND receipt.id=r.receipt_id
   WHERE r.tenant=t AND r.warehouse_id=p->>'warehouse_id' AND r.receipt_id=p->>'return_receipt_id'
   AND r.order_id=p->>'order_id' AND r.order_line_id=p->>'line_id' AND r.sku=s AND r.lot=l AND receipt.status<>'cancelled'));
 ELSIF status IN('in_transit','lost') THEN
  SELECT EXISTS(SELECT 1 FROM wms_transfer_lines line JOIN wms_products source ON source.tenant=line.tenant AND source.warehouse_id=line.source_warehouse_id AND source.sku=line.sku
   JOIN wms_products destination ON destination.tenant=line.tenant AND destination.warehouse_id=line.destination_warehouse_id AND destination.sku=line.sku
   WHERE line.tenant=t AND line.transfer_id=p->>'transfer_id' AND line.id=p->>'line_id' AND line.sku=s AND line.lot=l
   AND line.source_warehouse_id=p->>'source_warehouse_id' AND line.destination_warehouse_id=p->>'destination_warehouse_id'
   AND source.data->'serial_controlled'='true'::jsonb AND destination.data->'serial_controlled'='true'::jsonb) INTO valid;
  RETURN valid AND (status='in_transit' OR EXISTS(SELECT 1 FROM wms_transfer_loss_records r WHERE r.tenant=t AND r.id=p->>'loss_id' AND r.kind='loss'
   AND r.warehouse_id=p->>'destination_warehouse_id' AND r.transfer_id=p->>'transfer_id' AND r.line_id=p->>'line_id'));
 END IF;
 RETURN false;
END 

-- ------------------------------------------------------------------
-- wms_serial_place_valid(p jsonb) RETURNS boolean
-- LANGUAGE plpgsql IMMUTABLE
DECLARE required TEXT[]; k TEXT;
BEGIN
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' THEN RETURN false; END IF;
 CASE p->>'status'
 WHEN 'on_hand','missing' THEN required=ARRAY['status','warehouse_id','location'];
 WHEN 'staged' THEN required=ARRAY['status','warehouse_id','order_id','line_id','allocation_location','package_id'];
 WHEN 'shipped' THEN required=ARRAY['status','warehouse_id','order_id','line_id','package_id','handoff_event_id','return_receipt_id'];
 WHEN 'in_transit' THEN required=ARRAY['status','source_warehouse_id','destination_warehouse_id','transfer_id','line_id'];
 WHEN 'lost' THEN required=ARRAY['status','source_warehouse_id','destination_warehouse_id','transfer_id','line_id','loss_id'];
 ELSE RETURN false;
 END CASE;
 IF NOT p ?& required OR p-required<>'{}'::jsonb THEN RETURN false; END IF;
 FOREACH k IN ARRAY required LOOP
  IF k IN('package_id','return_receipt_id') AND p->k='null'::jsonb THEN CONTINUE; END IF;
  IF jsonb_typeof(p->k) IS DISTINCT FROM 'string' OR NOT wms_serial_text(p->>k) THEN RETURN false; END IF;
 END LOOP;
 RETURN NOT (p->>'status' IN('on_hand','missing') AND p->>'location'='STAGE-01')
  AND NOT (p->>'status' IN('in_transit','lost') AND p->>'source_warehouse_id'=p->>'destination_warehouse_id');
END 

-- ------------------------------------------------------------------
-- wms_serial_product_mode() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
DECLARE actual BOOLEAN; requested BOOLEAN;
BEGIN
 IF COALESCE(jsonb_typeof(NEW.data->'serial_controlled'),'boolean')<>'boolean' THEN
  RAISE EXCEPTION 'Serial mode requires an actual boolean' USING ERRCODE='23514';
 END IF;
 requested=COALESCE((NEW.data->>'serial_controlled')::boolean,false);
 IF TG_OP='UPDATE' AND (NEW.tenant,NEW.warehouse_id,NEW.sku,requested)
  IS DISTINCT FROM (OLD.tenant,OLD.warehouse_id,OLD.sku,COALESCE((OLD.data->>'serial_controlled')::boolean,false)) THEN
  RAISE EXCEPTION 'Product serial identity and mode cannot change after creation' USING ERRCODE='23514';
 END IF;
 INSERT INTO wms_serial_modes(tenant,sku,controlled) VALUES(NEW.tenant,NEW.sku,false)
  ON CONFLICT(tenant,sku) DO UPDATE SET sku=EXCLUDED.sku RETURNING controlled INTO actual;
 IF requested<>actual THEN
  RAISE EXCEPTION 'Every facility must retain the original tenant/SKU serial mode' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_serial_scope_commit() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
DECLARE d JSONB; t TEXT; w TEXT; source_sku TEXT; derived TEXT;
BEGIN
 IF TG_OP='DELETE' THEN d=to_jsonb(OLD); ELSE d=to_jsonb(NEW); END IF;
 t=d->>'tenant'; w=COALESCE(d->>'warehouse_id',d->>'source_warehouse_id',d->>'destination_warehouse_id'); source_sku=d->>'sku';
 IF source_sku IS NOT NULL AND NOT EXISTS(SELECT 1 FROM wms_serial_modes WHERE tenant=t AND sku=source_sku AND controlled) THEN RETURN NULL; END IF;
 IF NOT EXISTS(SELECT 1 FROM wms_serial_modes WHERE tenant=t AND controlled) THEN RETURN NULL; END IF;
 IF source_sku IS NOT NULL THEN
  PERFORM wms_serial_enqueue_sku_scope(t,w,source_sku);
  IF TG_OP='UPDATE' AND to_jsonb(OLD)->>'sku' IS DISTINCT FROM source_sku THEN
   PERFORM wms_serial_enqueue_sku_scope(t,COALESCE(to_jsonb(OLD)->>'warehouse_id',w),to_jsonb(OLD)->>'sku');
  END IF;
 ELSIF TG_TABLE_NAME='wms_package_closures' THEN
  FOR derived IN SELECT DISTINCT line.sku FROM wms_package_lines line
   WHERE line.tenant=t AND line.warehouse_id=w AND line.package_id=d->>'package_id' LOOP
   PERFORM wms_serial_enqueue_sku_scope(t,w,derived);
  END LOOP;
 ELSIF TG_TABLE_NAME='wms_receipts' THEN
  FOR derived IN SELECT DISTINCT r.sku FROM wms_return_lines r
   WHERE r.tenant=t AND r.warehouse_id=w AND r.receipt_id=d->>'id' LOOP
   PERFORM wms_serial_enqueue_sku_scope(t,w,derived);
  END LOOP;
 ELSIF TG_TABLE_NAME='wms_transfer_loss_records' THEN
  SELECT line.sku INTO derived FROM wms_transfer_lines line
   WHERE line.tenant=t AND line.transfer_id=d->>'transfer_id' AND line.id=d->>'line_id';
  IF FOUND THEN PERFORM wms_serial_enqueue_sku_scope(t,w,derived);
  ELSE INSERT INTO wms_serial_pending_checks VALUES(t,'scope',w) ON CONFLICT DO NOTHING; END IF;
 ELSIF TG_TABLE_NAME<>'wms_events' THEN
  INSERT INTO wms_serial_pending_checks VALUES(t,'scope',w) ON CONFLICT DO NOTHING;
 END IF;
 -- Mode-source selection is unchanged from migration 032.
 INSERT INTO wms_serial_pending_checks VALUES(t,CASE WHEN source_sku IS NULL THEN 'modes' ELSE 'mode' END,
  CASE WHEN source_sku IS NULL THEN w ELSE jsonb_build_array(w,source_sku)::text END) ON CONFLICT DO NOTHING;
 IF TG_TABLE_NAME='wms_events' THEN
  INSERT INTO wms_serial_pending_checks VALUES(t,'event',d->>'id') ON CONFLICT DO NOTHING;
 END IF;
 RETURN NULL;
END 

-- ------------------------------------------------------------------
-- wms_serial_scope_current_valid(t text, w text) RETURNS boolean
-- LANGUAGE sql STABLE
 WITH reference_classes AS MATERIALIZED (
  SELECT min(tenant) AS tenant,min(sku) AS sku,min(lot) AS lot,place,
   (place::text) COLLATE "C" AS place_key,count(*)::bigint AS quantity FROM wms_serial_units
  WHERE tenant=t AND (place->>'warehouse_id'=w OR place->>'source_warehouse_id'=w OR place->>'destination_warehouse_id'=w)
  GROUP BY tenant COLLATE "C",sku COLLATE "C",lot COLLATE "C",place,(place::text) COLLATE "C"
 ), reference_places AS MATERIALIZED (
  SELECT DISTINCT ON(place_key) place_key,place FROM reference_classes
  WHERE place->>'status' IN('on_hand','missing')
 ), reference_shapes AS MATERIALIZED (
  SELECT place_key,wms_serial_place_valid(place) AS shape FROM reference_places
 ), reference_sources AS MATERIALIZED (
  SELECT u.tenant,u.sku,u.lot,u.place,u.place_key,
   CASE WHEN u.place->>'status' IN('on_hand','missing') THEN
    CASE WHEN NOT shape.shape OR mode.sku IS NULL THEN false ELSE bin.code IS NOT NULL END
   ELSE wms_serial_place_references_valid(u.tenant,u.sku,u.lot,u.place) END AS ok
  FROM reference_classes u LEFT JOIN reference_shapes shape ON shape.place_key=u.place_key
  LEFT JOIN wms_serial_modes mode ON mode.tenant=u.tenant AND mode.sku=u.sku AND mode.controlled
  LEFT JOIN wms_products product ON product.tenant=u.tenant AND product.sku=u.sku
   AND product.warehouse_id=u.place->>'warehouse_id' AND product.data->'serial_controlled'='true'::jsonb
  LEFT JOIN wms_locations bin ON bin.tenant=product.tenant AND bin.warehouse_id=product.warehouse_id
   AND bin.code=u.place->>'location' AND bin.kind IN('storage','receiving')
 ), expected_stock AS (
  SELECT s.sku,s.lot,s.location,s.on_hand AS quantity FROM wms_stock s JOIN wms_serial_modes m ON m.tenant=s.tenant AND m.sku=s.sku AND m.controlled
  WHERE s.tenant=t AND s.warehouse_id=w
 ), actual_stock AS (
  SELECT sku,lot,CASE WHEN place->>'status'='staged' THEN 'STAGE-01' ELSE place->>'location' END AS location,sum(quantity)::bigint AS quantity
  FROM reference_classes WHERE place->>'warehouse_id'=w AND place->>'status' IN('on_hand','staged')
  GROUP BY sku,lot,CASE WHEN place->>'status'='staged' THEN 'STAGE-01' ELSE place->>'location' END
 ), expected_staged AS (
  SELECT a.order_id,a.line_id,a.location,a.sku,a.lot,(a.picked-a.shipped)::bigint AS quantity FROM wms_allocations a
  JOIN wms_serial_modes m ON m.tenant=a.tenant AND m.sku=a.sku AND m.controlled WHERE a.tenant=t AND a.warehouse_id=w
 ), actual_staged AS (
  SELECT place->>'order_id' AS order_id,place->>'line_id' AS line_id,place->>'allocation_location' AS location,sku,lot,sum(quantity)::bigint AS quantity
  FROM reference_classes WHERE place->>'warehouse_id'=w AND place->>'status'='staged'
  GROUP BY place->>'order_id',place->>'line_id',place->>'allocation_location',sku,lot
 ), expected_packages AS (
  SELECT line.package_id,line.line_id,line.location,line.sku,line.lot,line.quantity FROM wms_package_lines line
  JOIN wms_serial_modes m ON m.tenant=line.tenant AND m.sku=line.sku AND m.controlled WHERE line.tenant=t AND line.warehouse_id=w
  AND NOT EXISTS(SELECT 1 FROM wms_package_closures c WHERE c.tenant=line.tenant AND c.warehouse_id=line.warehouse_id AND c.package_id=line.package_id)
 ), actual_packages AS (
  SELECT place->>'package_id' AS package_id,place->>'line_id' AS line_id,place->>'allocation_location' AS location,sku,lot,sum(quantity)::bigint AS quantity
  FROM reference_classes WHERE place->>'warehouse_id'=w AND place->>'status'='staged' AND place->>'package_id' IS NOT NULL
  GROUP BY place->>'package_id',place->>'line_id',place->>'allocation_location',sku,lot
 )
 SELECT NOT EXISTS(SELECT 1 FROM expected_stock e FULL JOIN actual_stock a USING(sku,lot,location) WHERE COALESCE(e.quantity,0)<>COALESCE(a.quantity,0))
 AND NOT EXISTS(SELECT 1 FROM expected_staged e FULL JOIN actual_staged a USING(order_id,line_id,location,sku,lot) WHERE COALESCE(e.quantity,0)<>COALESCE(a.quantity,0))
 AND NOT EXISTS(SELECT 1 FROM expected_packages e FULL JOIN actual_packages a USING(package_id,line_id,location,sku,lot) WHERE COALESCE(e.quantity,0)<>COALESCE(a.quantity,0))
 AND NOT EXISTS(SELECT 1 FROM reference_sources WHERE NOT ok);

-- ------------------------------------------------------------------
-- wms_serial_scope_current_valid_sku(t text, w text, k_sku text) RETURNS boolean
-- LANGUAGE sql STABLE
 WITH reference_classes AS MATERIALIZED (
  SELECT min(tenant) AS tenant,min(sku) AS sku,min(lot) AS lot,place,
   (place::text) COLLATE "C" AS place_key,count(*)::bigint AS quantity FROM wms_serial_units
  WHERE tenant=t AND sku=k_sku AND (place->>'warehouse_id'=w OR place->>'source_warehouse_id'=w OR place->>'destination_warehouse_id'=w)
  GROUP BY tenant COLLATE "C",sku COLLATE "C",lot COLLATE "C",place,(place::text) COLLATE "C"
 ), reference_places AS MATERIALIZED (
  SELECT DISTINCT ON(place_key) place_key,place FROM reference_classes
  WHERE place->>'status' IN('on_hand','missing')
 ), reference_shapes AS MATERIALIZED (
  SELECT place_key,wms_serial_place_valid(place) AS shape FROM reference_places
 ), reference_sources AS MATERIALIZED (
  SELECT u.tenant,u.sku,u.lot,u.place,u.place_key,
   CASE WHEN u.place->>'status' IN('on_hand','missing') THEN
    CASE WHEN NOT shape.shape OR mode.sku IS NULL THEN false ELSE bin.code IS NOT NULL END
   ELSE wms_serial_place_references_valid(u.tenant,u.sku,u.lot,u.place) END AS ok
  FROM reference_classes u LEFT JOIN reference_shapes shape ON shape.place_key=u.place_key
  LEFT JOIN wms_serial_modes mode ON mode.tenant=u.tenant AND mode.sku=u.sku AND mode.controlled
  LEFT JOIN wms_products product ON product.tenant=u.tenant AND product.sku=u.sku
   AND product.warehouse_id=u.place->>'warehouse_id' AND product.data->'serial_controlled'='true'::jsonb
  LEFT JOIN wms_locations bin ON bin.tenant=product.tenant AND bin.warehouse_id=product.warehouse_id
   AND bin.code=u.place->>'location' AND bin.kind IN('storage','receiving')
 ), expected_stock AS (
  SELECT s.sku,s.lot,s.location,s.on_hand AS quantity FROM wms_stock s JOIN wms_serial_modes m ON m.tenant=s.tenant AND m.sku=s.sku AND m.controlled
  WHERE s.tenant=t AND s.warehouse_id=w AND s.sku=k_sku
 ), actual_stock AS (
  SELECT sku,lot,CASE WHEN place->>'status'='staged' THEN 'STAGE-01' ELSE place->>'location' END AS location,sum(quantity)::bigint AS quantity
  FROM reference_classes WHERE place->>'warehouse_id'=w AND place->>'status' IN('on_hand','staged')
  GROUP BY sku,lot,CASE WHEN place->>'status'='staged' THEN 'STAGE-01' ELSE place->>'location' END
 ), expected_staged AS (
  SELECT a.order_id,a.line_id,a.location,a.sku,a.lot,(a.picked-a.shipped)::bigint AS quantity FROM wms_allocations a
  JOIN wms_serial_modes m ON m.tenant=a.tenant AND m.sku=a.sku AND m.controlled WHERE a.tenant=t AND a.warehouse_id=w AND a.sku=k_sku
 ), actual_staged AS (
  SELECT place->>'order_id' AS order_id,place->>'line_id' AS line_id,place->>'allocation_location' AS location,sku,lot,sum(quantity)::bigint AS quantity
  FROM reference_classes WHERE place->>'warehouse_id'=w AND place->>'status'='staged'
  GROUP BY place->>'order_id',place->>'line_id',place->>'allocation_location',sku,lot
 ), expected_packages AS (
  SELECT line.package_id,line.line_id,line.location,line.sku,line.lot,line.quantity FROM wms_package_lines line
  JOIN wms_serial_modes m ON m.tenant=line.tenant AND m.sku=line.sku AND m.controlled WHERE line.tenant=t AND line.warehouse_id=w AND line.sku=k_sku
  AND NOT EXISTS(SELECT 1 FROM wms_package_closures c WHERE c.tenant=line.tenant AND c.warehouse_id=line.warehouse_id AND c.package_id=line.package_id)
 ), actual_packages AS (
  SELECT place->>'package_id' AS package_id,place->>'line_id' AS line_id,place->>'allocation_location' AS location,sku,lot,sum(quantity)::bigint AS quantity
  FROM reference_classes WHERE place->>'warehouse_id'=w AND place->>'status'='staged' AND place->>'package_id' IS NOT NULL
  GROUP BY place->>'package_id',place->>'line_id',place->>'allocation_location',sku,lot
 )
 SELECT NOT EXISTS(SELECT 1 FROM expected_stock e FULL JOIN actual_stock a USING(sku,lot,location) WHERE COALESCE(e.quantity,0)<>COALESCE(a.quantity,0))
 AND NOT EXISTS(SELECT 1 FROM expected_staged e FULL JOIN actual_staged a USING(order_id,line_id,location,sku,lot) WHERE COALESCE(e.quantity,0)<>COALESCE(a.quantity,0))
 AND NOT EXISTS(SELECT 1 FROM expected_packages e FULL JOIN actual_packages a USING(package_id,line_id,location,sku,lot) WHERE COALESCE(e.quantity,0)<>COALESCE(a.quantity,0))
 AND NOT EXISTS(SELECT 1 FROM reference_sources WHERE NOT ok);

-- ------------------------------------------------------------------
-- wms_serial_scope_transit_valid(t text, w text) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT NOT EXISTS(SELECT 1 FROM wms_transfer_lines line JOIN wms_serial_modes mode ON mode.tenant=line.tenant AND mode.sku=line.sku AND mode.controlled
  WHERE line.tenant=t AND (line.source_warehouse_id=w OR line.destination_warehouse_id=w)
  AND line.quantity - COALESCE((SELECT sum(m.quantity) FROM wms_movements m WHERE m.tenant=line.tenant AND m.warehouse_id=line.destination_warehouse_id
   AND m.transfer_id=line.transfer_id AND m.transfer_line_id=line.id AND m.kind='transfer_receive'),0)
  <> (SELECT count(*) FROM wms_serial_units unit WHERE unit.tenant=line.tenant AND unit.sku=line.sku AND unit.lot=line.lot
   AND unit.place->>'transfer_id'=line.transfer_id AND unit.place->>'line_id'=line.id AND unit.place->>'status' IN('in_transit','lost')))
 AND NOT EXISTS(SELECT 1 FROM wms_transfer_loss_records loss JOIN wms_transfer_lines line ON line.tenant=loss.tenant AND line.transfer_id=loss.transfer_id AND line.id=loss.line_id
  JOIN wms_serial_modes mode ON mode.tenant=line.tenant AND mode.sku=line.sku AND mode.controlled
  WHERE loss.tenant=t AND loss.kind='loss' AND (line.source_warehouse_id=w OR line.destination_warehouse_id=w)
  AND loss.quantity-COALESCE((SELECT sum(reversal.quantity) FROM wms_transfer_loss_records reversal WHERE reversal.tenant=loss.tenant AND reversal.original_loss_id=loss.id AND reversal.kind='reversal'),0)
  <> (SELECT count(*) FROM wms_serial_units unit WHERE unit.tenant=line.tenant AND unit.sku=line.sku AND unit.lot=line.lot AND unit.place->>'status'='lost'
   AND unit.place->>'loss_id'=loss.id AND unit.place->>'transfer_id'=line.transfer_id AND unit.place->>'line_id'=line.id));

-- ------------------------------------------------------------------
-- wms_serial_scope_transit_valid_sku(t text, w text, k_sku text) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT NOT EXISTS(SELECT 1 FROM wms_transfer_lines line JOIN wms_serial_modes mode ON mode.tenant=line.tenant AND mode.sku=line.sku AND mode.controlled
  WHERE line.tenant=t AND line.sku=k_sku AND (line.source_warehouse_id=w OR line.destination_warehouse_id=w)
  AND line.quantity - COALESCE((SELECT sum(m.quantity) FROM wms_movements m WHERE m.tenant=line.tenant AND m.warehouse_id=line.destination_warehouse_id
   AND m.transfer_id=line.transfer_id AND m.transfer_line_id=line.id AND m.kind='transfer_receive'),0)
  <> (SELECT count(*) FROM wms_serial_units unit WHERE unit.tenant=line.tenant AND unit.sku=line.sku AND unit.lot=line.lot
   AND unit.place->>'transfer_id'=line.transfer_id AND unit.place->>'line_id'=line.id AND unit.place->>'status' IN('in_transit','lost')))
 AND NOT EXISTS(SELECT 1 FROM wms_transfer_loss_records loss JOIN wms_transfer_lines line ON line.tenant=loss.tenant AND line.transfer_id=loss.transfer_id AND line.id=loss.line_id
  JOIN wms_serial_modes mode ON mode.tenant=line.tenant AND mode.sku=line.sku AND mode.controlled
  WHERE loss.tenant=t AND loss.kind='loss' AND line.sku=k_sku AND (line.source_warehouse_id=w OR line.destination_warehouse_id=w)
  AND loss.quantity-COALESCE((SELECT sum(reversal.quantity) FROM wms_transfer_loss_records reversal WHERE reversal.tenant=loss.tenant AND reversal.original_loss_id=loss.id AND reversal.kind='reversal'),0)
  <> (SELECT count(*) FROM wms_serial_units unit WHERE unit.tenant=line.tenant AND unit.sku=line.sku AND unit.lot=line.lot AND unit.place->>'status'='lost'
   AND unit.place->>'loss_id'=loss.id AND unit.place->>'transfer_id'=line.transfer_id AND unit.place->>'line_id'=line.id));

-- ------------------------------------------------------------------
-- wms_serial_shipped(w text, o text, line text, package text, eid text) RETURNS jsonb
-- LANGUAGE sql IMMUTABLE
 SELECT jsonb_build_object('status','shipped','warehouse_id',w,'order_id',o,'line_id',line,'package_id',package,'handoff_event_id',eid,'return_receipt_id',NULL);

-- ------------------------------------------------------------------
-- wms_serial_staged(w text, o text, line text, b text, package text) RETURNS jsonb
-- LANGUAGE sql IMMUTABLE
 SELECT jsonb_build_object('status','staged','warehouse_id',w,'order_id',o,'line_id',line,'allocation_location',b,'package_id',package);

-- ------------------------------------------------------------------
-- wms_serial_step_bound(s wms_serial_steps) RETURNS boolean
-- LANGUAGE plpgsql STABLE
DECLARE original_payload JSONB;
BEGIN
 SELECT payload||'{}'::jsonb INTO original_payload FROM wms_events WHERE id=s.event_id;
 IF NOT FOUND THEN RETURN false; END IF;
 RETURN (SELECT EXISTS(SELECT 1 FROM wms_events e JOIN wms_commands c ON c.tenant=e.tenant AND c.warehouse_id=e.warehouse_id AND c.request_id=original_payload->>'request_id'
 JOIN wms_serial_batches b ON b.tenant=s.tenant AND b.sku=s.sku AND b.version=s.sku_version AND b.event_id=s.event_id AND b.warehouse_id=s.warehouse_id AND b.warehouse_version=s.warehouse_version
 WHERE e.id=s.event_id AND e.tenant=s.tenant AND e.warehouse_id=s.warehouse_id AND e.version=s.warehouse_version
 AND original_payload->>'actor'=s.actor AND c.actor=s.actor AND original_payload->>'occurred_at'=s.recorded_at
 AND original_payload->'result'=c.result AND wms_serial_batch_original(b)
 AND original_payload->'serial_steps'->(s.ordinal-1)=to_jsonb(s)-'tenant' AND wms_serial_step_semantic_valid(s)
 AND (s.revision=1 OR EXISTS(SELECT 1 FROM wms_serial_steps previous
  WHERE previous.tenant=s.tenant AND previous.sku=s.sku AND previous.serial=s.serial AND previous.revision=s.previous_revision
  AND previous.lot=s.lot AND previous.after_place=s.before_place AND previous.sku_version<s.sku_version))));
END 

-- ------------------------------------------------------------------
-- wms_serial_step_effect_valid(s wms_serial_steps, e jsonb, observed boolean, count_observation boolean) RETURNS boolean
-- LANGUAGE plpgsql STABLE
DECLARE c JSONB; command_type TEXT; expected_kind TEXT; original RECORD; matched BOOLEAN=false;
BEGIN
 c=e->'command'; command_type=c->>'type';
 expected_kind=CASE command_type
  WHEN 'count_stock' THEN 'inventory.counted' WHEN 'move_stock' THEN 'inventory.moved'
  WHEN 'receive' THEN 'receipt.received' WHEN 'pick' THEN 'fulfillment.picked' WHEN 'unpick' THEN 'fulfillment.unpicked'
  WHEN 'create_return' THEN 'return.authorized' WHEN 'cancel_receipt' THEN 'receipt.cancelled'
  WHEN 'pack_shipment' THEN 'shipment.packed' WHEN 'unpack_shipment' THEN 'shipment.unpacked'
  WHEN 'handoff_shipment' THEN 'shipment.handed_off' WHEN 'ship' THEN 'fulfillment.shipped'
  WHEN 'dispatch_transfer' THEN 'transfer.dispatched' WHEN 'receive_transfer' THEN 'transfer.received'
  WHEN 'record_transfer_loss' THEN 'transfer.loss_recorded' WHEN 'reverse_transfer_loss' THEN 'transfer.loss_reversed' END;
 IF expected_kind IS NULL OR e->>'type' IS DISTINCT FROM expected_kind OR e->'result'->>'type' IS DISTINCT FROM expected_kind
  OR NOT wms_serial_place_valid(s.after_place) OR (s.before_place IS NOT NULL AND NOT wms_serial_place_valid(s.before_place)) THEN RETURN false; END IF;

 IF command_type='count_stock' THEN
  RETURN COALESCE(s.target='[]'::jsonb AND s.sku=c->>'sku' AND s.lot=c->>'lot' AND (
   (observed AND s.after_place=wms_serial_on_hand(s.warehouse_id,c->>'location') AND (s.before_place IS NULL
    OR s.before_place=wms_serial_on_hand(s.warehouse_id,c->>'location')
    OR (s.before_place->>'status'='missing' AND s.before_place->>'warehouse_id'=s.warehouse_id)))
   OR (NOT observed AND s.before_place=wms_serial_on_hand(s.warehouse_id,c->>'location')
    AND s.after_place=jsonb_build_object('status','missing','warehouse_id',s.warehouse_id,'location',c->>'location')
    AND count_observation)),false);
 ELSIF command_type='move_stock' THEN
  RETURN COALESCE(observed AND s.target='[]'::jsonb AND s.sku=c->>'sku' AND s.lot=c->>'lot'
   AND s.before_place=wms_serial_on_hand(s.warehouse_id,c->>'from') AND s.after_place=wms_serial_on_hand(s.warehouse_id,c->>'to'),false);
 ELSIF command_type IN('pick','unpick') THEN
  IF NOT observed OR s.target<>'[]'::jsonb OR s.lot IS DISTINCT FROM c->>'lot'
   OR NOT EXISTS(SELECT 1 FROM wms_order_lines line WHERE line.tenant=s.tenant AND line.warehouse_id=s.warehouse_id
    AND line.order_id=c->>'order_id' AND line.id=c->>'line_id' AND line.sku=s.sku) THEN RETURN false; END IF;
  IF command_type='pick' THEN RETURN s.before_place=wms_serial_on_hand(s.warehouse_id,c->>'location')
   AND s.after_place=wms_serial_staged(s.warehouse_id,c->>'order_id',c->>'line_id',c->>'location',NULL);
  ELSE RETURN s.before_place=wms_serial_staged(s.warehouse_id,c->>'order_id',c->>'line_id',c->>'location',NULL)
   AND s.after_place=wms_serial_on_hand(s.warehouse_id,c->>'location'); END IF;
 ELSIF command_type='receive' THEN
  IF NOT observed OR s.target<>'[]'::jsonb OR s.after_place<>wms_serial_on_hand(s.warehouse_id,c->>'location') THEN RETURN false; END IF;
  SELECT line.*,r.order_id,r.order_line_id INTO original FROM wms_receipt_lines line LEFT JOIN wms_return_lines r
   ON r.tenant=line.tenant AND r.warehouse_id=line.warehouse_id AND r.receipt_id=line.receipt_id AND r.line_id=line.id
   WHERE line.tenant=s.tenant AND line.warehouse_id=s.warehouse_id AND line.receipt_id=c->>'receipt_id' AND line.id=c->>'line_id' AND line.sku=s.sku AND line.lot=s.lot;
  IF NOT FOUND THEN RETURN false; END IF;
  IF original.order_id IS NULL THEN RETURN s.before_place IS NULL; END IF;
  RETURN COALESCE(s.before_place->>'status'='shipped' AND s.before_place->>'warehouse_id'=s.warehouse_id
   AND s.before_place->>'order_id'=original.order_id AND s.before_place->>'line_id'=original.order_line_id
   AND s.before_place->>'return_receipt_id'=c->>'receipt_id',false);
 ELSIF command_type='create_return' THEN
  IF NOT observed OR jsonb_array_length(s.target)<>1 OR s.before_place->>'status' IS DISTINCT FROM 'shipped'
   OR s.before_place->'return_receipt_id' IS DISTINCT FROM 'null'::jsonb THEN RETURN false; END IF;
  SELECT r.* INTO original FROM wms_return_lines r
   JOIN LATERAL jsonb_array_elements(c->'lines') AS command_line(doc) ON command_line.doc->>'id'=r.line_id
   WHERE r.tenant=s.tenant AND r.warehouse_id=s.warehouse_id AND r.receipt_id=e->'result'->>'entity_id'
   AND r.line_id=s.target->>0 AND r.order_id=c->>'order_id' AND r.sku=s.sku AND r.lot=s.lot
   AND command_line.doc->>'order_line_id'=r.order_line_id AND command_line.doc->>'lot'=r.lot
   AND command_line.doc->'quantity'=to_jsonb(r.quantity) AND r.reason=c->>'reason'
   AND e#>>'{receipt,id}'=r.receipt_id AND e#>>'{receipt,reference}'=c->>'reference'
   AND e#>>'{receipt,return_source,order_id}'=r.order_id AND e#>>'{receipt,return_source,reason}'=r.reason
   AND e#>'{receipt,return_source,line_ids}'->>r.line_id=r.order_line_id
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(e#>'{receipt,lines}') AS receipt_line(doc)
    WHERE receipt_line.doc=jsonb_build_object('id',r.line_id,'sku',r.sku,'lot',r.lot,'quantity',r.quantity,'received',0));
  RETURN COALESCE(FOUND AND s.before_place->>'warehouse_id'=s.warehouse_id AND s.before_place->>'order_id'=original.order_id
   AND s.before_place->>'line_id'=original.order_line_id
   AND s.after_place=s.before_place || jsonb_build_object('return_receipt_id',e->'result'->>'entity_id'),false);
 ELSIF command_type='cancel_receipt' THEN
  RETURN COALESCE(s.target='[]'::jsonb AND s.before_place->>'status'='shipped' AND s.before_place->>'warehouse_id'=s.warehouse_id
   AND s.before_place->>'return_receipt_id'=c->>'receipt_id' AND s.after_place=s.before_place || '{"return_receipt_id":null}'::jsonb
   AND EXISTS(SELECT 1 FROM wms_return_lines r JOIN wms_receipt_cancellations cancellation
    ON cancellation.tenant=r.tenant AND cancellation.warehouse_id=r.warehouse_id AND cancellation.receipt_id=r.receipt_id
    WHERE r.tenant=s.tenant AND r.warehouse_id=s.warehouse_id AND r.receipt_id=c->>'receipt_id' AND r.sku=s.sku AND r.lot=s.lot
    AND r.order_id=s.before_place->>'order_id' AND r.order_line_id=s.before_place->>'line_id'
    AND cancellation.actor=s.actor AND cancellation.reason=c->>'reason' AND cancellation.cancelled_at=e#>>'{receipt,cancellation,cancelled_at}'
    AND e#>>'{receipt,id}'=c->>'receipt_id' AND e#>>'{receipt,status}'='cancelled'),false);
 ELSIF command_type='pack_shipment' THEN
  IF NOT observed OR jsonb_array_length(s.target)<>3 THEN RETURN false; END IF;
  RETURN COALESCE(s.lot=s.target->>2 AND s.before_place=wms_serial_staged(s.warehouse_id,c->>'order_id',s.target->>0,s.target->>1,NULL)
   AND s.after_place=s.before_place || jsonb_build_object('package_id',e->'result'->>'entity_id')
   AND EXISTS(SELECT 1 FROM wms_package_lines line JOIN wms_packages p ON p.tenant=line.tenant AND p.warehouse_id=line.warehouse_id AND p.id=line.package_id
    WHERE line.tenant=s.tenant AND line.warehouse_id=s.warehouse_id AND line.package_id=e->'result'->>'entity_id' AND line.order_id=c->>'order_id'
    AND line.line_id=s.target->>0 AND line.location=s.target->>1 AND line.sku=s.sku AND line.lot=s.lot AND p.source_event_id=s.event_id),false);
 ELSIF command_type IN('unpack_shipment','handoff_shipment') THEN
  IF s.target<>'[]'::jsonb THEN RETURN false; END IF;
  SELECT line.* INTO original FROM wms_package_lines line JOIN wms_package_closures closure
   ON closure.tenant=line.tenant AND closure.warehouse_id=line.warehouse_id AND closure.package_id=line.package_id
   WHERE line.tenant=s.tenant AND line.warehouse_id=s.warehouse_id AND line.package_id=c->>'shipment_id' AND line.sku=s.sku AND line.lot=s.lot
   AND line.line_id=s.before_place->>'line_id' AND line.location=s.before_place->>'allocation_location'
   AND closure.event_id=s.event_id AND closure.kind=CASE WHEN command_type='unpack_shipment' THEN 'unpacked' ELSE 'handed_off' END;
  IF NOT FOUND OR s.before_place IS DISTINCT FROM wms_serial_staged(s.warehouse_id,original.order_id,original.line_id,original.location,original.package_id) THEN RETURN false; END IF;
  IF command_type='unpack_shipment' THEN RETURN s.after_place=s.before_place || '{"package_id":null}'::jsonb;
  ELSE RETURN s.after_place=wms_serial_shipped(s.warehouse_id,original.order_id,original.line_id,original.package_id,s.event_id); END IF;
 ELSIF command_type='ship' THEN
  RETURN COALESCE(s.target='[]'::jsonb AND s.before_place=wms_serial_staged(s.warehouse_id,c->>'order_id',s.before_place->>'line_id',s.before_place->>'allocation_location',NULL)
   AND s.after_place=wms_serial_shipped(s.warehouse_id,c->>'order_id',s.before_place->>'line_id',NULL,s.event_id)
   AND EXISTS(SELECT 1 FROM wms_shipment_evidence h JOIN wms_allocations a ON a.tenant=h.tenant AND a.warehouse_id=h.warehouse_id AND a.order_id=h.order_id
    WHERE h.tenant=s.tenant AND h.warehouse_id=s.warehouse_id AND h.order_id=c->>'order_id' AND h.source_kind='event' AND h.event_id=s.event_id
    AND a.line_id=s.before_place->>'line_id' AND a.location=s.before_place->>'allocation_location' AND a.sku=s.sku AND a.lot=s.lot),false);
 ELSIF command_type='dispatch_transfer' THEN
  IF NOT observed OR jsonb_array_length(s.target)<>1 THEN RETURN false; END IF;
  SELECT line.* INTO original FROM wms_transfer_lines line JOIN wms_transfers transfer ON transfer.tenant=line.tenant AND transfer.id=line.transfer_id
   WHERE line.tenant=s.tenant AND line.source_warehouse_id=s.warehouse_id AND line.transfer_id=e->'result'->>'entity_id' AND line.id=s.target->>0
   AND line.sku=s.sku AND line.lot=s.lot AND line.destination_warehouse_id=c->>'destination_warehouse_id' AND transfer.source_event_id=s.event_id;
  RETURN COALESCE(FOUND AND s.before_place=wms_serial_on_hand(s.warehouse_id,original.location)
   AND s.after_place=wms_serial_transit(s.warehouse_id,original.destination_warehouse_id,original.transfer_id,original.id),false);
 ELSIF command_type IN('receive_transfer','record_transfer_loss') THEN
  IF NOT observed OR s.target<>'[]'::jsonb THEN RETURN false; END IF;
  SELECT line.* INTO original FROM wms_transfer_lines line WHERE line.tenant=s.tenant AND line.destination_warehouse_id=s.warehouse_id
   AND line.transfer_id=c->>'transfer_id' AND line.id=c->>'line_id' AND line.sku=s.sku AND line.lot=s.lot;
  IF NOT FOUND OR s.before_place IS DISTINCT FROM wms_serial_transit(original.source_warehouse_id,s.warehouse_id,original.transfer_id,original.id) THEN RETURN false; END IF;
  IF command_type='receive_transfer' THEN RETURN s.after_place=wms_serial_on_hand(s.warehouse_id,c->>'location'); END IF;
  RETURN s.after_place=jsonb_build_object('status','lost','source_warehouse_id',original.source_warehouse_id,'destination_warehouse_id',s.warehouse_id,
   'transfer_id',original.transfer_id,'line_id',original.id,'loss_id',e->'result'->>'entity_id')
   AND EXISTS(SELECT 1 FROM wms_transfer_loss_records loss WHERE loss.tenant=s.tenant AND loss.warehouse_id=s.warehouse_id
    AND loss.id=e->'result'->>'entity_id' AND loss.kind='loss' AND loss.transfer_id=original.transfer_id AND loss.line_id=original.id AND loss.event_id=s.event_id);
 ELSIF command_type='reverse_transfer_loss' THEN
  IF NOT observed OR s.target<>'[]'::jsonb THEN RETURN false; END IF;
  SELECT line.*,loss.id AS original_loss_id INTO original FROM wms_transfer_lines line JOIN wms_transfer_loss_records loss
   ON loss.tenant=line.tenant AND loss.transfer_id=line.transfer_id AND loss.line_id=line.id
   WHERE line.tenant=s.tenant AND line.destination_warehouse_id=s.warehouse_id AND loss.warehouse_id=s.warehouse_id AND loss.kind='loss'
   AND loss.id=c->>'loss_id' AND line.sku=s.sku AND line.lot=s.lot;
  RETURN COALESCE(FOUND AND s.before_place=jsonb_build_object('status','lost','source_warehouse_id',original.source_warehouse_id,'destination_warehouse_id',s.warehouse_id,
    'transfer_id',original.transfer_id,'line_id',original.id,'loss_id',original.original_loss_id)
   AND s.after_place=wms_serial_transit(original.source_warehouse_id,s.warehouse_id,original.transfer_id,original.id)
   AND EXISTS(SELECT 1 FROM wms_transfer_loss_records reversal WHERE reversal.tenant=s.tenant AND reversal.warehouse_id=s.warehouse_id
    AND reversal.kind='reversal' AND reversal.original_loss_id=original.original_loss_id AND reversal.event_id=s.event_id AND reversal.id=e->'result'->>'entity_id'),false);
 END IF;
 RETURN false;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END 

-- ------------------------------------------------------------------
-- wms_serial_step_semantic_valid(s wms_serial_steps) RETURNS boolean
-- LANGUAGE plpgsql STABLE
DECLARE e JSONB; c JSONB; command_type TEXT; expected_kind TEXT; observed BOOLEAN; original RECORD; matched BOOLEAN=false;
BEGIN
 SELECT payload||'{}'::jsonb INTO e FROM wms_events WHERE id=s.event_id AND tenant=s.tenant AND warehouse_id=s.warehouse_id AND version=s.warehouse_version;
 IF NOT FOUND THEN RETURN false; END IF;
 c=e->'command'; command_type=c->>'type';
 expected_kind=CASE command_type
  WHEN 'count_stock' THEN 'inventory.counted' WHEN 'move_stock' THEN 'inventory.moved'
  WHEN 'receive' THEN 'receipt.received' WHEN 'pick' THEN 'fulfillment.picked' WHEN 'unpick' THEN 'fulfillment.unpicked'
  WHEN 'create_return' THEN 'return.authorized' WHEN 'cancel_receipt' THEN 'receipt.cancelled'
  WHEN 'pack_shipment' THEN 'shipment.packed' WHEN 'unpack_shipment' THEN 'shipment.unpacked'
  WHEN 'handoff_shipment' THEN 'shipment.handed_off' WHEN 'ship' THEN 'fulfillment.shipped'
  WHEN 'dispatch_transfer' THEN 'transfer.dispatched' WHEN 'receive_transfer' THEN 'transfer.received'
  WHEN 'record_transfer_loss' THEN 'transfer.loss_recorded' WHEN 'reverse_transfer_loss' THEN 'transfer.loss_reversed' END;
 IF expected_kind IS NULL OR e->>'type' IS DISTINCT FROM expected_kind OR e->'result'->>'type' IS DISTINCT FROM expected_kind
  OR NOT wms_serial_place_valid(s.after_place) OR (s.before_place IS NOT NULL AND NOT wms_serial_place_valid(s.before_place)) THEN RETURN false; END IF;
 SELECT EXISTS(SELECT 1 FROM wms_serial_observations obs WHERE obs.tenant=s.tenant AND obs.warehouse_id=s.warehouse_id
  AND obs.event_id=s.event_id AND obs.sku=s.sku AND obs.target=s.target AND obs.serials @> jsonb_build_array(s.serial)
  AND wms_serial_observation_bound(obs)) INTO observed;
 IF command_type='count_stock' THEN
  RETURN COALESCE(s.target='[]'::jsonb AND s.sku=c->>'sku' AND s.lot=c->>'lot' AND (
   (observed AND s.after_place=wms_serial_on_hand(s.warehouse_id,c->>'location') AND (s.before_place IS NULL
    OR s.before_place=wms_serial_on_hand(s.warehouse_id,c->>'location')
    OR (s.before_place->>'status'='missing' AND s.before_place->>'warehouse_id'=s.warehouse_id)))
   OR (NOT observed AND s.before_place=wms_serial_on_hand(s.warehouse_id,c->>'location')
    AND s.after_place=jsonb_build_object('status','missing','warehouse_id',s.warehouse_id,'location',c->>'location')
    AND EXISTS(SELECT 1 FROM wms_serial_observations obs WHERE obs.tenant=s.tenant AND obs.warehouse_id=s.warehouse_id AND obs.event_id=s.event_id
     AND obs.sku=s.sku AND obs.target='[]'::jsonb AND wms_serial_observation_bound(obs)))),false);
 ELSIF command_type='move_stock' THEN
  RETURN COALESCE(observed AND s.target='[]'::jsonb AND s.sku=c->>'sku' AND s.lot=c->>'lot'
   AND s.before_place=wms_serial_on_hand(s.warehouse_id,c->>'from') AND s.after_place=wms_serial_on_hand(s.warehouse_id,c->>'to'),false);
 ELSIF command_type IN('pick','unpick') THEN
  IF NOT observed OR s.target<>'[]'::jsonb OR s.lot IS DISTINCT FROM c->>'lot'
   OR NOT EXISTS(SELECT 1 FROM wms_order_lines line WHERE line.tenant=s.tenant AND line.warehouse_id=s.warehouse_id
    AND line.order_id=c->>'order_id' AND line.id=c->>'line_id' AND line.sku=s.sku) THEN RETURN false; END IF;
  IF command_type='pick' THEN RETURN s.before_place=wms_serial_on_hand(s.warehouse_id,c->>'location')
   AND s.after_place=wms_serial_staged(s.warehouse_id,c->>'order_id',c->>'line_id',c->>'location',NULL);
  ELSE RETURN s.before_place=wms_serial_staged(s.warehouse_id,c->>'order_id',c->>'line_id',c->>'location',NULL)
   AND s.after_place=wms_serial_on_hand(s.warehouse_id,c->>'location'); END IF;
 ELSIF command_type='receive' THEN
  IF NOT observed OR s.target<>'[]'::jsonb OR s.after_place<>wms_serial_on_hand(s.warehouse_id,c->>'location') THEN RETURN false; END IF;
  SELECT line.*,r.order_id,r.order_line_id INTO original FROM wms_receipt_lines line LEFT JOIN wms_return_lines r
   ON r.tenant=line.tenant AND r.warehouse_id=line.warehouse_id AND r.receipt_id=line.receipt_id AND r.line_id=line.id
   WHERE line.tenant=s.tenant AND line.warehouse_id=s.warehouse_id AND line.receipt_id=c->>'receipt_id' AND line.id=c->>'line_id' AND line.sku=s.sku AND line.lot=s.lot;
  IF NOT FOUND THEN RETURN false; END IF;
  IF original.order_id IS NULL THEN RETURN s.before_place IS NULL; END IF;
  RETURN COALESCE(s.before_place->>'status'='shipped' AND s.before_place->>'warehouse_id'=s.warehouse_id
   AND s.before_place->>'order_id'=original.order_id AND s.before_place->>'line_id'=original.order_line_id
   AND s.before_place->>'return_receipt_id'=c->>'receipt_id',false);
 ELSIF command_type='create_return' THEN
  IF NOT observed OR jsonb_array_length(s.target)<>1 OR s.before_place->>'status' IS DISTINCT FROM 'shipped'
   OR s.before_place->'return_receipt_id' IS DISTINCT FROM 'null'::jsonb THEN RETURN false; END IF;
  SELECT r.* INTO original FROM wms_return_lines r
   JOIN LATERAL jsonb_array_elements(c->'lines') AS command_line(doc) ON command_line.doc->>'id'=r.line_id
   WHERE r.tenant=s.tenant AND r.warehouse_id=s.warehouse_id AND r.receipt_id=e->'result'->>'entity_id'
   AND r.line_id=s.target->>0 AND r.order_id=c->>'order_id' AND r.sku=s.sku AND r.lot=s.lot
   AND command_line.doc->>'order_line_id'=r.order_line_id AND command_line.doc->>'lot'=r.lot
   AND command_line.doc->'quantity'=to_jsonb(r.quantity) AND r.reason=c->>'reason'
   AND e#>>'{receipt,id}'=r.receipt_id AND e#>>'{receipt,reference}'=c->>'reference'
   AND e#>>'{receipt,return_source,order_id}'=r.order_id AND e#>>'{receipt,return_source,reason}'=r.reason
   AND e#>'{receipt,return_source,line_ids}'->>r.line_id=r.order_line_id
   AND EXISTS(SELECT 1 FROM jsonb_array_elements(e#>'{receipt,lines}') AS receipt_line(doc)
    WHERE receipt_line.doc=jsonb_build_object('id',r.line_id,'sku',r.sku,'lot',r.lot,'quantity',r.quantity,'received',0));
  RETURN COALESCE(FOUND AND s.before_place->>'warehouse_id'=s.warehouse_id AND s.before_place->>'order_id'=original.order_id
   AND s.before_place->>'line_id'=original.order_line_id
   AND s.after_place=s.before_place || jsonb_build_object('return_receipt_id',e->'result'->>'entity_id'),false);
 ELSIF command_type='cancel_receipt' THEN
  RETURN COALESCE(s.target='[]'::jsonb AND s.before_place->>'status'='shipped' AND s.before_place->>'warehouse_id'=s.warehouse_id
   AND s.before_place->>'return_receipt_id'=c->>'receipt_id' AND s.after_place=s.before_place || '{"return_receipt_id":null}'::jsonb
   AND EXISTS(SELECT 1 FROM wms_return_lines r JOIN wms_receipt_cancellations cancellation
    ON cancellation.tenant=r.tenant AND cancellation.warehouse_id=r.warehouse_id AND cancellation.receipt_id=r.receipt_id
    WHERE r.tenant=s.tenant AND r.warehouse_id=s.warehouse_id AND r.receipt_id=c->>'receipt_id' AND r.sku=s.sku AND r.lot=s.lot
    AND r.order_id=s.before_place->>'order_id' AND r.order_line_id=s.before_place->>'line_id'
    AND cancellation.actor=s.actor AND cancellation.reason=c->>'reason' AND cancellation.cancelled_at=e#>>'{receipt,cancellation,cancelled_at}'
    AND e#>>'{receipt,id}'=c->>'receipt_id' AND e#>>'{receipt,status}'='cancelled'),false);
 ELSIF command_type='pack_shipment' THEN
  IF NOT observed OR jsonb_array_length(s.target)<>3 THEN RETURN false; END IF;
  RETURN COALESCE(s.lot=s.target->>2 AND s.before_place=wms_serial_staged(s.warehouse_id,c->>'order_id',s.target->>0,s.target->>1,NULL)
   AND s.after_place=s.before_place || jsonb_build_object('package_id',e->'result'->>'entity_id')
   AND EXISTS(SELECT 1 FROM wms_package_lines line JOIN wms_packages p ON p.tenant=line.tenant AND p.warehouse_id=line.warehouse_id AND p.id=line.package_id
    WHERE line.tenant=s.tenant AND line.warehouse_id=s.warehouse_id AND line.package_id=e->'result'->>'entity_id' AND line.order_id=c->>'order_id'
    AND line.line_id=s.target->>0 AND line.location=s.target->>1 AND line.sku=s.sku AND line.lot=s.lot AND p.source_event_id=s.event_id),false);
 ELSIF command_type IN('unpack_shipment','handoff_shipment') THEN
  IF s.target<>'[]'::jsonb THEN RETURN false; END IF;
  SELECT line.* INTO original FROM wms_package_lines line JOIN wms_package_closures closure
   ON closure.tenant=line.tenant AND closure.warehouse_id=line.warehouse_id AND closure.package_id=line.package_id
   WHERE line.tenant=s.tenant AND line.warehouse_id=s.warehouse_id AND line.package_id=c->>'shipment_id' AND line.sku=s.sku AND line.lot=s.lot
   AND line.line_id=s.before_place->>'line_id' AND line.location=s.before_place->>'allocation_location'
   AND closure.event_id=s.event_id AND closure.kind=CASE WHEN command_type='unpack_shipment' THEN 'unpacked' ELSE 'handed_off' END;
  IF NOT FOUND OR s.before_place IS DISTINCT FROM wms_serial_staged(s.warehouse_id,original.order_id,original.line_id,original.location,original.package_id) THEN RETURN false; END IF;
  IF command_type='unpack_shipment' THEN RETURN s.after_place=s.before_place || '{"package_id":null}'::jsonb;
  ELSE RETURN s.after_place=wms_serial_shipped(s.warehouse_id,original.order_id,original.line_id,original.package_id,s.event_id); END IF;
 ELSIF command_type='ship' THEN
  RETURN COALESCE(s.target='[]'::jsonb AND s.before_place=wms_serial_staged(s.warehouse_id,c->>'order_id',s.before_place->>'line_id',s.before_place->>'allocation_location',NULL)
   AND s.after_place=wms_serial_shipped(s.warehouse_id,c->>'order_id',s.before_place->>'line_id',NULL,s.event_id)
   AND EXISTS(SELECT 1 FROM wms_shipment_evidence h JOIN wms_allocations a ON a.tenant=h.tenant AND a.warehouse_id=h.warehouse_id AND a.order_id=h.order_id
    WHERE h.tenant=s.tenant AND h.warehouse_id=s.warehouse_id AND h.order_id=c->>'order_id' AND h.source_kind='event' AND h.event_id=s.event_id
    AND a.line_id=s.before_place->>'line_id' AND a.location=s.before_place->>'allocation_location' AND a.sku=s.sku AND a.lot=s.lot),false);
 ELSIF command_type='dispatch_transfer' THEN
  IF NOT observed OR jsonb_array_length(s.target)<>1 THEN RETURN false; END IF;
  SELECT line.* INTO original FROM wms_transfer_lines line JOIN wms_transfers transfer ON transfer.tenant=line.tenant AND transfer.id=line.transfer_id
   WHERE line.tenant=s.tenant AND line.source_warehouse_id=s.warehouse_id AND line.transfer_id=e->'result'->>'entity_id' AND line.id=s.target->>0
   AND line.sku=s.sku AND line.lot=s.lot AND line.destination_warehouse_id=c->>'destination_warehouse_id' AND transfer.source_event_id=s.event_id;
  RETURN COALESCE(FOUND AND s.before_place=wms_serial_on_hand(s.warehouse_id,original.location)
   AND s.after_place=wms_serial_transit(s.warehouse_id,original.destination_warehouse_id,original.transfer_id,original.id),false);
 ELSIF command_type IN('receive_transfer','record_transfer_loss') THEN
  IF NOT observed OR s.target<>'[]'::jsonb THEN RETURN false; END IF;
  SELECT line.* INTO original FROM wms_transfer_lines line WHERE line.tenant=s.tenant AND line.destination_warehouse_id=s.warehouse_id
   AND line.transfer_id=c->>'transfer_id' AND line.id=c->>'line_id' AND line.sku=s.sku AND line.lot=s.lot;
  IF NOT FOUND OR s.before_place IS DISTINCT FROM wms_serial_transit(original.source_warehouse_id,s.warehouse_id,original.transfer_id,original.id) THEN RETURN false; END IF;
  IF command_type='receive_transfer' THEN RETURN s.after_place=wms_serial_on_hand(s.warehouse_id,c->>'location'); END IF;
  RETURN s.after_place=jsonb_build_object('status','lost','source_warehouse_id',original.source_warehouse_id,'destination_warehouse_id',s.warehouse_id,
   'transfer_id',original.transfer_id,'line_id',original.id,'loss_id',e->'result'->>'entity_id')
   AND EXISTS(SELECT 1 FROM wms_transfer_loss_records loss WHERE loss.tenant=s.tenant AND loss.warehouse_id=s.warehouse_id
    AND loss.id=e->'result'->>'entity_id' AND loss.kind='loss' AND loss.transfer_id=original.transfer_id AND loss.line_id=original.id AND loss.event_id=s.event_id);
 ELSIF command_type='reverse_transfer_loss' THEN
  IF NOT observed OR s.target<>'[]'::jsonb THEN RETURN false; END IF;
  SELECT line.*,loss.id AS original_loss_id INTO original FROM wms_transfer_lines line JOIN wms_transfer_loss_records loss
   ON loss.tenant=line.tenant AND loss.transfer_id=line.transfer_id AND loss.line_id=line.id
   WHERE line.tenant=s.tenant AND line.destination_warehouse_id=s.warehouse_id AND loss.warehouse_id=s.warehouse_id AND loss.kind='loss'
   AND loss.id=c->>'loss_id' AND line.sku=s.sku AND line.lot=s.lot;
  RETURN COALESCE(FOUND AND s.before_place=jsonb_build_object('status','lost','source_warehouse_id',original.source_warehouse_id,'destination_warehouse_id',s.warehouse_id,
    'transfer_id',original.transfer_id,'line_id',original.id,'loss_id',original.original_loss_id)
   AND s.after_place=wms_serial_transit(original.source_warehouse_id,s.warehouse_id,original.transfer_id,original.id)
   AND EXISTS(SELECT 1 FROM wms_transfer_loss_records reversal WHERE reversal.tenant=s.tenant AND reversal.warehouse_id=s.warehouse_id
    AND reversal.kind='reversal' AND reversal.original_loss_id=original.original_loss_id AND reversal.event_id=s.event_id AND reversal.id=e->'result'->>'entity_id'),false);
 END IF;
 RETURN false;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END 

-- ------------------------------------------------------------------
-- wms_serial_step_source_for_event(s wms_serial_steps, observed boolean, count_observation boolean) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT EXISTS(SELECT 1 FROM wms_events e JOIN wms_commands c ON c.tenant=e.tenant AND c.warehouse_id=e.warehouse_id AND c.request_id=e.payload->>'request_id'
 JOIN wms_serial_batches b ON b.tenant=s.tenant AND b.sku=s.sku AND b.version=s.sku_version AND b.event_id=s.event_id AND b.warehouse_id=s.warehouse_id AND b.warehouse_version=s.warehouse_version
 WHERE e.id=s.event_id AND e.tenant=s.tenant AND e.warehouse_id=s.warehouse_id AND e.version=s.warehouse_version
 AND e.payload->>'actor'=s.actor AND c.actor=s.actor AND e.payload->>'occurred_at'=s.recorded_at
 AND e.payload->'result'=c.result AND wms_serial_batch_original(b)
 AND e.payload->'serial_steps'->(s.ordinal-1)=to_jsonb(s)-'tenant' AND wms_serial_step_effect_valid(s,e.payload,observed,count_observation)
 AND (s.revision=1 OR EXISTS(SELECT 1 FROM wms_serial_steps previous
  WHERE previous.tenant=s.tenant AND previous.sku=s.sku AND previous.serial=s.serial AND previous.revision=s.previous_revision
  AND previous.lot=s.lot AND previous.after_place=s.before_place AND previous.sku_version<s.sku_version)));

-- ------------------------------------------------------------------
-- wms_serial_targets(t text, w text, c jsonb) RETURNS TABLE(target jsonb, sku text, each_quantity bigint, allow_zero boolean)
-- LANGUAGE plpgsql STABLE
BEGIN
 IF c->>'type'='move_stock' AND NOT (c ?| ARRAY['counted','lines']) THEN
  RETURN QUERY SELECT '[]'::jsonb,c->>'sku',(c->>'quantity')::bigint,false;
 ELSIF c->>'type'='count_stock' AND NOT (c ?| ARRAY['quantity','lines']) THEN
  RETURN QUERY SELECT '[]'::jsonb,c->>'sku',(c->>'counted')::bigint,true;
 ELSE
  RETURN QUERY SELECT q.* FROM wms_unit_targets(t,w,c) q WHERE c->>'type' IN(
   'count_stock','move_stock','receive','pick','unpick','create_return','pack_shipment',
   'dispatch_transfer','receive_transfer','record_transfer_loss','reverse_transfer_loss');
 END IF;
END 

-- ------------------------------------------------------------------
-- wms_serial_text(s text) RETURNS boolean
-- LANGUAGE sql IMMUTABLE
 SELECT CASE WHEN octet_length(s) BETWEEN 1 AND 240
  AND s COLLATE "C" ~ '^[!-~]([ -~]*[!-~])?$' THEN true
 ELSE COALESCE(octet_length(s) BETWEEN 1 AND 240
  AND s=btrim(s,U&'\0009\000A\000B\000C\000D\0020\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000')
  AND s !~ '[[:cntrl:]]' AND s !~ U&'[\007F-\009F]',false) END;

-- ------------------------------------------------------------------
-- wms_serial_transit(source text, destination text, transfer text, line text) RETURNS jsonb
-- LANGUAGE sql IMMUTABLE
 SELECT jsonb_build_object('status','in_transit','source_warehouse_id',source,'destination_warehouse_id',destination,'transfer_id',transfer,'line_id',line);

-- ------------------------------------------------------------------
-- wms_serial_unit_bound(u wms_serial_units) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT EXISTS(SELECT 1 FROM wms_serial_steps s WHERE s.tenant=u.tenant AND s.sku=u.sku AND s.serial=u.serial
  AND s.lot=u.lot AND s.revision=u.revision AND s.event_id=u.last_event_id AND s.after_place=u.place AND wms_serial_step_bound(s))
 AND NOT EXISTS(SELECT 1 FROM wms_serial_steps s WHERE s.tenant=u.tenant AND s.sku=u.sku AND s.serial=u.serial AND s.revision>u.revision);

-- ------------------------------------------------------------------
-- wms_serial_unit_identity() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
BEGIN
 IF TG_OP='DELETE' OR (NEW.tenant,NEW.sku,NEW.serial,NEW.lot) IS DISTINCT FROM (OLD.tenant,OLD.sku,OLD.serial,OLD.lot)
  OR NEW.revision<>OLD.revision+1 OR NEW.last_event_id=OLD.last_event_id THEN
  RAISE EXCEPTION 'Serialized units retain their original identity and advance one original event at a time' USING ERRCODE='23514';
 END IF;
 RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_serial_validate_pending() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
DECLARE source_warehouse TEXT; valid BOOLEAN;
BEGIN
 -- Removal never means acceptance. Any failed check aborts this transaction,
 -- restoring its dirty keys along with the original physical/source mutations.
 DELETE FROM wms_serial_pending_checks WHERE tenant=NEW.tenant AND kind=NEW.kind AND key=NEW.key;
 IF NEW.kind IN('mode','modes') THEN
  IF wms_serial_modes_original_for_scope(NEW.tenant,CASE WHEN NEW.kind='mode' THEN (NEW.key::jsonb)->>1 END) IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'Original serial mode source disagrees' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.kind='scope' THEN
  IF wms_serial_scope_current_valid(NEW.tenant,NEW.key) IS DISTINCT FROM true
   OR wms_serial_scope_transit_valid(NEW.tenant,NEW.key) IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'Serialized stock, staging, package, transit or original loss ownership disagrees' USING ERRCODE='23514';
  END IF;
 ELSIF NEW.kind='sku_scope' THEN
  IF wms_serial_scope_current_valid_sku(NEW.tenant,(NEW.key::jsonb)->>0,(NEW.key::jsonb)->>1) IS DISTINCT FROM true
   OR wms_serial_scope_transit_valid_sku(NEW.tenant,(NEW.key::jsonb)->>0,(NEW.key::jsonb)->>1) IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'Serialized stock, staging, package, transit or original loss ownership disagrees' USING ERRCODE='23514';
  END IF;
 ELSE
  SELECT warehouse_id INTO source_warehouse FROM wms_events WHERE tenant=NEW.tenant AND id=NEW.key;
  IF NOT FOUND OR wms_serial_event_valid_read_source(NEW.tenant,source_warehouse,NEW.key) IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'Original serial source event lacks complete exact inputs, effects or source relationships' USING ERRCODE='23514';
  END IF;
  WITH affected AS MATERIALIZED (
   SELECT sku,serial FROM wms_serial_steps WHERE tenant=NEW.tenant AND event_id=NEW.key
   UNION SELECT sku,serial FROM wms_serial_units WHERE tenant=NEW.tenant AND last_event_id=NEW.key
  ), current_units AS MATERIALIZED (
   SELECT u.* FROM affected k LEFT JOIN wms_serial_units u ON u.tenant=NEW.tenant AND u.sku=k.sku AND u.serial=k.serial
  ), latest_events AS MATERIALIZED (
   SELECT e.id,e.warehouse_id,
    CASE WHEN e.id=NEW.key THEN true ELSE wms_serial_event_valid_read_source(e.tenant,e.warehouse_id,e.id) END AS ok
   FROM wms_events e JOIN (SELECT DISTINCT last_event_id FROM current_units) k ON k.last_event_id=e.id
   WHERE e.tenant=NEW.tenant
  ) SELECT NOT EXISTS(
   SELECT 1 FROM current_units u LEFT JOIN latest_events e ON e.id=u.last_event_id
   WHERE u.tenant IS NULL OR e.ok IS DISTINCT FROM true
    OR NOT EXISTS(SELECT 1 FROM wms_serial_steps s WHERE s.tenant=u.tenant AND s.sku=u.sku AND s.serial=u.serial
     AND s.lot=u.lot AND s.revision=u.revision AND s.event_id=u.last_event_id AND s.after_place=u.place AND s.warehouse_id=e.warehouse_id)
    OR EXISTS(SELECT 1 FROM wms_serial_steps later WHERE later.tenant=u.tenant AND later.sku=u.sku AND later.serial=u.serial AND later.revision>u.revision)
  ) INTO valid;
  IF valid IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'Original serial source, revision chain or current projection disagrees' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NULL;
END 

-- ------------------------------------------------------------------
-- wms_serialize_shipment(t text, w text) RETURNS void
-- LANGUAGE sql VOLATILE
 -- A prior write by this transaction already holds the head lock. Avoid another
 -- row version per allocation in many-lot picks. After transaction-ID wrap the
 -- 64-bit/32-bit comparison conservatively stops skipping rather than aliasing.
 UPDATE wms_warehouses SET version=version WHERE tenant=t AND warehouse_id=w AND xmin::text::bigint<>txid_current();

-- ------------------------------------------------------------------
-- wms_shipment_commit_proof() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
BEGIN
 IF NOT wms_shipment_consistent(NEW.tenant,NEW.warehouse_id,NEW.order_id) THEN
  RAISE EXCEPTION 'Committed shipment facts or movements changed during recording' USING ERRCODE='23514';
 END IF;
 RETURN NULL;
END 

-- ------------------------------------------------------------------
-- wms_shipment_consistent(t text, w text, o text) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT CASE WHEN EXISTS(SELECT 1 FROM wms_split_orders WHERE tenant=t AND warehouse_id=w AND order_id=o)
 THEN wms_split_consistent(t,w,o) AND EXISTS(SELECT 1 FROM wms_package_closures WHERE tenant=t AND warehouse_id=w AND order_id=o AND kind='handed_off')
 ELSE COALESCE((SELECT wms_shipment_facts_match(t,w,o,e.document) FROM wms_shipment_evidence e WHERE e.tenant=t AND e.warehouse_id=w AND e.order_id=o),false) END;

-- ------------------------------------------------------------------
-- wms_shipment_facts_match(t text, w text, o text, d jsonb) RETURNS boolean
-- LANGUAGE plpgsql STABLE
DECLARE current_document JSONB; field TEXT;
BEGIN
 current_document=wms_current_order(t,w,o);
 IF d IS NULL OR current_document IS NULL OR d IS DISTINCT FROM current_document
  OR d->>'status' IS DISTINCT FROM 'shipped' THEN RETURN false; END IF;
 FOREACH field IN ARRAY ARRAY['id','reference','customer','destination','priority','carrier','handoff_reference','created_at','shipped_at'] LOOP
  IF jsonb_typeof(d->field) IS DISTINCT FROM 'string' OR length(btrim(d->>field))=0 THEN RETURN false; END IF;
 END LOOP;
 IF jsonb_typeof(d->'source_order_id') NOT IN('null','string') OR d->>'priority' NOT IN('normal','high','urgent')
  OR jsonb_array_length(d->'lines')=0 OR jsonb_array_length(d->'allocations')=0 THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM wms_allocations a WHERE a.tenant=t AND a.warehouse_id=w AND a.order_id=o
   AND (a.picked<>a.quantity OR a.shipped<>a.quantity OR a.released<>0))
 OR EXISTS(SELECT 1 FROM wms_order_lines l WHERE l.tenant=t AND l.warehouse_id=w AND l.order_id=o
   AND l.quantity<>(SELECT COALESCE(sum(a.shipped),0) FROM wms_allocations a WHERE a.tenant=t AND a.warehouse_id=w AND a.order_id=o AND a.line_id=l.id))
 OR EXISTS(SELECT 1 FROM wms_movements m WHERE m.tenant=t AND m.warehouse_id=w AND m.kind='shipment' AND m.reference=d->>'reference'
   AND (m.from_location IS DISTINCT FROM 'STAGE-01' OR m.to_location IS NOT NULL)) THEN RETURN false; END IF;
 RETURN NOT EXISTS(
  SELECT 1 FROM (SELECT a.sku,a.lot,sum(a.shipped) AS quantity FROM wms_allocations a WHERE a.tenant=t AND a.warehouse_id=w AND a.order_id=o GROUP BY a.sku,a.lot) expected
  FULL JOIN (SELECT m.sku,m.lot,sum(m.quantity) AS quantity FROM wms_movements m WHERE m.tenant=t AND m.warehouse_id=w AND m.kind='shipment' AND m.reference=d->>'reference' GROUP BY m.sku,m.lot) physical USING(sku,lot)
  WHERE expected.quantity IS DISTINCT FROM physical.quantity);
END 

-- ------------------------------------------------------------------
-- wms_shipment_movement_guard() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
BEGIN
 PERFORM wms_serialize_shipment(NEW.tenant,NEW.warehouse_id);
 IF NEW.package_id IS NULL AND (EXISTS(SELECT 1 FROM wms_shipment_evidence e WHERE e.tenant=NEW.tenant AND e.warehouse_id=NEW.warehouse_id AND e.document->>'reference'=NEW.reference)
 OR EXISTS(SELECT 1 FROM wms_orders o WHERE o.tenant=NEW.tenant AND o.warehouse_id=NEW.warehouse_id AND o.reference=NEW.reference AND o.data->>'shipment_mode'='packages')) THEN
 RAISE EXCEPTION 'Shipment movement requires its exact original handoff ownership' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_shipment_movement_required() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
BEGIN
 IF NEW.package_id IS NULL AND NOT EXISTS(SELECT 1 FROM wms_shipment_evidence e WHERE e.tenant=NEW.tenant AND e.warehouse_id=NEW.warehouse_id AND e.document->>'reference'=NEW.reference) THEN
 RAISE EXCEPTION 'Shipment movement requires its original completed order evidence' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END 

-- ------------------------------------------------------------------
-- wms_shipment_source_guard() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
DECLARE source JSONB; source_version BIGINT;
BEGIN
 PERFORM wms_serialize_shipment(NEW.tenant,NEW.warehouse_id);
 IF NEW.source_version>(SELECT version FROM wms_warehouses WHERE tenant=NEW.tenant AND warehouse_id=NEW.warehouse_id) THEN
  RAISE EXCEPTION 'Shipment source version cannot exceed the warehouse history' USING ERRCODE='23514';
 END IF;
 IF NEW.document IS DISTINCT FROM wms_canonical_order(NEW.document)
  OR NOT wms_shipment_facts_match(NEW.tenant,NEW.warehouse_id,NEW.order_id,NEW.document) THEN
  RAISE EXCEPTION 'Shipment evidence disagrees with canonical order or physical handoff movements' USING ERRCODE='23514';
 END IF;
 IF NEW.source_kind='event' THEN
  SELECT payload,version INTO source,source_version FROM wms_events WHERE id=NEW.event_id AND tenant=NEW.tenant AND warehouse_id=NEW.warehouse_id;
  IF NOT FOUND OR source_version<>NEW.source_version
   OR source->>'type' IS DISTINCT FROM 'fulfillment.shipped' OR source->>'id' IS DISTINCT FROM NEW.event_id
   OR source->>'tenant' IS DISTINCT FROM NEW.tenant OR source->>'warehouse_id' IS DISTINCT FROM NEW.warehouse_id
   OR source->'version' IS DISTINCT FROM to_jsonb(source_version)
   OR source#>>'{command,type}' IS DISTINCT FROM 'ship' OR source#>>'{command,order_id}' IS DISTINCT FROM NEW.order_id
   OR source#>>'{command,carrier}' IS DISTINCT FROM NEW.document->>'carrier'
   OR source#>>'{command,handoff_reference}' IS DISTINCT FROM NEW.document->>'handoff_reference'
   OR source#>>'{result,entity_id}' IS DISTINCT FROM NEW.order_id OR source#>'{result,version}' IS DISTINCT FROM to_jsonb(source_version)
   OR wms_canonical_order(source->'order') IS DISTINCT FROM NEW.document THEN
   RAISE EXCEPTION 'Shipment evidence requires its exact scoped committed handoff event' USING ERRCODE='23514';
  END IF;
 ELSE
  IF EXISTS(SELECT 1 FROM wms_events WHERE tenant=NEW.tenant AND warehouse_id=NEW.warehouse_id AND payload->>'type'='fulfillment.shipped' AND payload#>>'{order,id}'=NEW.order_id) THEN
   RAISE EXCEPTION 'An existing physical event cannot be replaced by a shipment baseline' USING ERRCODE='23514';
  END IF;
  IF NEW.source_kind='legacy_snapshot' THEN
   SELECT s.state,s.version INTO source,source_version FROM wms_workspaces s WHERE s.tenant=NEW.tenant AND s.warehouse_id=NEW.warehouse_id;
   IF NOT FOUND OR source_version<>NEW.source_version OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(source->'orders') a WHERE a->>'id'=NEW.order_id AND wms_canonical_order(a)=NEW.document) THEN
    RAISE EXCEPTION 'Shipment baseline requires the original retained legacy snapshot' USING ERRCODE='23514';
   END IF;
  ELSIF NEW.warehouse_id<>'wh-pdx' OR NOT EXISTS(SELECT 1 FROM wms_activity a WHERE a.tenant=NEW.tenant AND a.warehouse_id=NEW.warehouse_id
    AND a.data->>'actor'='fixture:synthetic' AND a.data->>'kind'='fulfillment.shipped' AND a.data->>'reference'=NEW.order_id) THEN
   RAISE EXCEPTION 'Synthetic shipment baselines require the disclosed original demo fixture' USING ERRCODE='23514';
  END IF;
 END IF;
 RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_split_before_order() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
DECLARE b JSONB;
BEGIN
 SELECT document INTO b FROM wms_split_orders WHERE tenant=OLD.tenant AND warehouse_id=OLD.warehouse_id AND order_id=OLD.id;
 IF FOUND AND (TG_OP='DELETE' OR (NEW.tenant,NEW.warehouse_id,NEW.id) IS DISTINCT FROM (OLD.tenant,OLD.warehouse_id,OLD.id)
  OR NEW.data->>'shipment_mode' IS DISTINCT FROM 'packages' OR wms_split_header(NEW.data) IS DISTINCT FROM b-'lines') THEN
 RAISE EXCEPTION 'Original split fulfillment contract and mode are immutable' USING ERRCODE='23514'; END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_split_commit() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
DECLARE o TEXT;r RECORD;
BEGIN
 IF TG_OP='DELETE' THEN r=OLD;ELSE r=NEW;END IF;
 IF TG_TABLE_NAME='wms_movements' THEN SELECT order_id INTO o FROM wms_packages WHERE tenant=r.tenant AND warehouse_id=r.warehouse_id AND id=r.package_id;
 ELSIF TG_TABLE_NAME='wms_orders' THEN o=r.id;ELSE o=r.order_id;END IF;
 IF o IS NOT NULL AND (EXISTS(SELECT 1 FROM wms_split_orders WHERE tenant=r.tenant AND warehouse_id=r.warehouse_id AND order_id=o)
 OR EXISTS(SELECT 1 FROM wms_orders WHERE tenant=r.tenant AND warehouse_id=r.warehouse_id AND id=o AND data->>'shipment_mode'='packages'))
 AND NOT COALESCE(wms_split_consistent(r.tenant,r.warehouse_id,o),false) THEN
 RAISE EXCEPTION 'Split fulfillment lacks exact packing, physical handoff or reservation evidence' USING ERRCODE='23514';END IF;RETURN NULL;
END 

-- ------------------------------------------------------------------
-- wms_split_consistent(t text, w text, o text) RETURNS boolean
-- LANGUAGE plpgsql STABLE
DECLARE b RECORD; h RECORD; terminal RECORD; e RECORD; d JSONB; expected JSONB; n BIGINT; latest RECORD;
BEGIN
 SELECT * INTO b FROM wms_split_orders WHERE tenant=t AND warehouse_id=w AND order_id=o;
 IF NOT FOUND THEN RETURN false; END IF;
 d=wms_current_order(t,w,o);
 IF NOT COALESCE(wms_order_cancellation_consistent(t,w,o),false) THEN RETURN false; END IF;
 IF d IS NULL OR d->>'shipment_mode' IS DISTINCT FROM 'packages' OR wms_split_contract(d) IS DISTINCT FROM b.document THEN RETURN false; END IF;
 SELECT * INTO e FROM wms_events WHERE id=b.source_event_id AND tenant=t AND warehouse_id=w AND version=b.source_version;
 IF NOT FOUND OR b.source_version>(SELECT version FROM wms_warehouses WHERE tenant=t AND warehouse_id=w)
 OR e.payload->>'type' IS DISTINCT FROM (CASE e.payload#>>'{command,type}' WHEN 'allocate_available' THEN 'fulfillment.available_allocated' WHEN 'pack_shipment' THEN 'shipment.packed' ELSE 'invalid' END)
 OR COALESCE(e.payload#>>'{command,type}','') NOT IN('allocate_available','pack_shipment') OR e.payload#>>'{command,order_id}' IS DISTINCT FROM o
 OR e.payload->>'id' IS DISTINCT FROM e.id OR e.payload->>'tenant' IS DISTINCT FROM t OR e.payload->>'warehouse_id' IS DISTINCT FROM w
 OR e.payload->'version' IS DISTINCT FROM to_jsonb(e.version) OR wms_split_contract(e.payload->'order') IS DISTINCT FROM b.document THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM wms_shipment_evidence WHERE tenant=t AND warehouse_id=w AND order_id=o)
 OR EXISTS(SELECT 1 FROM wms_movements WHERE tenant=t AND warehouse_id=w AND kind='shipment' AND reference=d->>'reference' AND package_id IS NULL)
 OR EXISTS(SELECT 1 FROM wms_order_lines l WHERE l.tenant=t AND l.warehouse_id=w AND l.order_id=o AND l.quantity<
  (SELECT COALESCE(sum(a.quantity-a.released),0) FROM wms_allocations a WHERE a.tenant=t AND a.warehouse_id=w AND a.order_id=o AND a.line_id=l.id)) THEN RETURN false; END IF;
 FOR h IN SELECT * FROM wms_packages WHERE tenant=t AND warehouse_id=w AND order_id=o LOOP
  SELECT * INTO e FROM wms_events WHERE id=h.source_event_id AND tenant=t AND warehouse_id=w AND version=h.source_version;
  IF NOT FOUND OR h.source_version<b.source_version OR h.source_version>(SELECT version FROM wms_warehouses WHERE tenant=t AND warehouse_id=w)
  OR e.payload->>'type' IS DISTINCT FROM 'shipment.packed' OR e.payload->>'id' IS DISTINCT FROM e.id
  OR e.payload->>'tenant' IS DISTINCT FROM t OR e.payload->>'warehouse_id' IS DISTINCT FROM w OR e.payload->'version' IS DISTINCT FROM to_jsonb(e.version)
  OR e.payload->'shipment' IS DISTINCT FROM (wms_package_document(t,w,h.id)||jsonb_build_object('closure',NULL))
  OR wms_split_contract(e.payload->'order') IS DISTINCT FROM b.document
  OR e.payload->>'actor' IS DISTINCT FROM h.actor OR e.payload#>>'{command,type}' IS DISTINCT FROM 'pack_shipment'
  OR e.payload#>>'{command,order_id}' IS DISTINCT FROM o OR e.payload#>>'{command,reference}' IS DISTINCT FROM h.reference
  OR e.payload#>>'{result,entity_id}' IS DISTINCT FROM h.id OR e.payload#>'{result,version}' IS DISTINCT FROM to_jsonb(e.version) THEN RETURN false; END IF;
  SELECT jsonb_agg(jsonb_build_object('line_id',l.line_id,'location',l.location,'lot',l.lot,'quantity',l.quantity) ORDER BY l.line_id,l.location,l.lot) INTO expected
   FROM wms_package_lines l WHERE l.tenant=t AND l.warehouse_id=w AND l.package_id=h.id;
  IF expected IS NULL OR jsonb_array_length(expected)>100 OR expected IS DISTINCT FROM wms_package_command_lines(e.payload#>'{command,lines}') THEN RETURN false; END IF;
  SELECT * INTO terminal FROM wms_package_closures WHERE tenant=t AND warehouse_id=w AND package_id=h.id;
  IF FOUND THEN
   SELECT * INTO e FROM wms_events WHERE id=terminal.event_id AND tenant=t AND warehouse_id=w AND version=terminal.version;
   IF NOT FOUND OR terminal.version<=h.source_version OR terminal.version>(SELECT version FROM wms_warehouses WHERE tenant=t AND warehouse_id=w)
   OR e.payload->>'type' IS DISTINCT FROM (CASE terminal.kind WHEN 'handed_off' THEN 'shipment.handed_off' ELSE 'shipment.unpacked' END)
   OR e.payload->>'id' IS DISTINCT FROM e.id OR e.payload->>'tenant' IS DISTINCT FROM t OR e.payload->>'warehouse_id' IS DISTINCT FROM w OR e.payload->'version' IS DISTINCT FROM to_jsonb(e.version)
   OR e.payload->'shipment' IS DISTINCT FROM wms_package_document(t,w,h.id)
   OR wms_split_contract(e.payload->'order') IS DISTINCT FROM b.document
   OR e.payload->>'actor' IS DISTINCT FROM terminal.actor OR e.payload#>>'{command,shipment_id}' IS DISTINCT FROM h.id
   OR e.payload#>>'{command,type}' IS DISTINCT FROM (CASE terminal.kind WHEN 'handed_off' THEN 'handoff_shipment' ELSE 'unpack_shipment' END)
   OR e.payload#>>'{result,entity_id}' IS DISTINCT FROM h.id OR e.payload#>'{result,version}' IS DISTINCT FROM to_jsonb(e.version)
   OR (terminal.kind='handed_off' AND (e.payload#>>'{command,carrier}' IS DISTINCT FROM terminal.carrier OR e.payload#>>'{command,handoff_reference}' IS DISTINCT FROM terminal.handoff_reference))
   OR (terminal.kind='unpacked' AND e.payload#>>'{command,reason}' IS DISTINCT FROM terminal.reason) THEN RETURN false; END IF;
  END IF;
  IF EXISTS(SELECT 1 FROM wms_package_lines l LEFT JOIN wms_movements m ON m.tenant=l.tenant AND m.warehouse_id=l.warehouse_id AND m.package_id=l.package_id
    AND m.order_line_id=l.line_id AND m.allocation_location=l.location AND m.lot=l.lot
   WHERE l.tenant=t AND l.warehouse_id=w AND l.package_id=h.id AND (
   (terminal.kind='handed_off' AND (m.id IS NULL OR m.kind<>'shipment' OR m.sku<>l.sku OR m.quantity<>l.quantity OR m.from_location IS DISTINCT FROM 'STAGE-01' OR m.to_location IS NOT NULL
    OR m.reference IS DISTINCT FROM d->>'reference' OR m.shipment_event_id IS DISTINCT FROM terminal.event_id OR m.data->>'actor' IS DISTINCT FROM terminal.actor
    OR m.data->>'at' IS DISTINCT FROM terminal.closed_at OR m.data->>'reason' IS DISTINCT FROM terminal.handoff_reference))
   OR (terminal.kind IS DISTINCT FROM 'handed_off' AND m.id IS NOT NULL))) THEN RETURN false; END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM wms_allocations a WHERE a.tenant=t AND a.warehouse_id=w AND a.order_id=o AND (
 a.shipped<>(SELECT COALESCE(sum(l.quantity),0) FROM wms_package_lines l JOIN wms_package_closures c ON c.tenant=l.tenant AND c.warehouse_id=l.warehouse_id AND c.package_id=l.package_id AND c.kind='handed_off'
  WHERE l.tenant=t AND l.warehouse_id=w AND l.order_id=o AND l.line_id=a.line_id AND l.location=a.location AND l.lot=a.lot)
 OR a.picked-a.shipped<(SELECT COALESCE(sum(l.quantity),0) FROM wms_package_lines l LEFT JOIN wms_package_closures c ON c.tenant=l.tenant AND c.warehouse_id=l.warehouse_id AND c.package_id=l.package_id
  WHERE l.tenant=t AND l.warehouse_id=w AND l.order_id=o AND l.line_id=a.line_id AND l.location=a.location AND l.lot=a.lot AND c.package_id IS NULL))) THEN RETURN false; END IF;
 IF d->>'status'='cancelled' THEN
  IF EXISTS(SELECT 1 FROM wms_allocations WHERE tenant=t AND warehouse_id=w AND order_id=o AND (picked<>0 OR shipped<>0 OR released<>quantity))
   OR EXISTS(SELECT 1 FROM wms_packages p LEFT JOIN wms_package_closures c ON c.tenant=p.tenant AND c.warehouse_id=p.warehouse_id AND c.package_id=p.id WHERE p.tenant=t AND p.warehouse_id=w AND p.order_id=o AND c.kind IS DISTINCT FROM 'unpacked') THEN RETURN false; END IF;
 ELSIF d->>'status' IS DISTINCT FROM wms_split_status(t,w,o) THEN RETURN false; END IF;
 SELECT count(*) INTO n FROM wms_package_closures WHERE tenant=t AND warehouse_id=w AND order_id=o AND kind='handed_off';
 IF n=0 THEN RETURN d->>'carrier'='' AND d->>'handoff_reference'='' AND d->'shipped_at'='null'::jsonb; END IF;
 SELECT * INTO latest FROM wms_package_closures WHERE tenant=t AND warehouse_id=w AND order_id=o AND kind='handed_off' ORDER BY version DESC LIMIT 1;
 RETURN d->>'shipped_at'=latest.closed_at AND CASE WHEN n=1 THEN d->>'carrier'=latest.carrier AND d->>'handoff_reference'=latest.handoff_reference ELSE d->>'carrier'='' AND d->>'handoff_reference'='' END;
END 

-- ------------------------------------------------------------------
-- wms_split_contract(d jsonb) RETURNS jsonb
-- LANGUAGE sql IMMUTABLE
 SELECT CASE WHEN jsonb_typeof(d->'lines')='array' THEN wms_split_header(d)||jsonb_build_object('lines',
 COALESCE((SELECT jsonb_agg(jsonb_build_object('id',l->'id','sku',l->'sku','quantity',l->'quantity') ORDER BY l->>'id') FROM jsonb_array_elements(d->'lines') l),'[]'::jsonb)) END;

-- ------------------------------------------------------------------
-- wms_split_header(d jsonb) RETURNS jsonb
-- LANGUAGE sql IMMUTABLE
 SELECT jsonb_build_object('id',d->'id','reference',d->'reference','source_order_id',d->'source_order_id','customer',d->'customer','destination',d->'destination','priority',d->'priority','created_at',d->'created_at');

-- ------------------------------------------------------------------
-- wms_split_line_identity() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
BEGIN
 IF EXISTS(SELECT 1 FROM wms_split_orders WHERE tenant=NEW.tenant AND warehouse_id=NEW.warehouse_id AND order_id=NEW.order_id)
 AND NOT EXISTS(SELECT 1 FROM wms_order_lines WHERE tenant=NEW.tenant AND warehouse_id=NEW.warehouse_id AND order_id=NEW.order_id AND id=NEW.id AND sku=NEW.sku AND quantity=NEW.quantity) THEN
 RAISE EXCEPTION 'Original split order lines cannot be added or replaced' USING ERRCODE='23514'; END IF;RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_split_lock() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
 BEGIN
 PERFORM wms_serialize_shipment(NEW.tenant,NEW.warehouse_id);
 PERFORM wms_bump_resource(NEW.tenant,NEW.warehouse_id,jsonb_build_array('order',NEW.order_id));
 RETURN NEW;END 

-- ------------------------------------------------------------------
-- wms_split_status(t text, w text, o text) RETURNS text
-- LANGUAGE sql STABLE
 SELECT CASE WHEN EXISTS(SELECT 1 FROM wms_order_cancellations WHERE tenant=t AND warehouse_id=w AND order_id=o) THEN 'closed_partial' WHEN q.shipped=q.ordered THEN 'shipped' WHEN q.shipped>0 THEN 'partially_shipped' WHEN q.picked=q.ordered THEN 'picked'
 WHEN q.picked>0 THEN 'picking' WHEN q.allocated>0 THEN 'allocated' ELSE 'pending' END FROM
 (SELECT (SELECT sum(quantity) FROM wms_order_lines WHERE tenant=t AND warehouse_id=w AND order_id=o) AS ordered,
 COALESCE(sum(shipped),0) AS shipped,COALESCE(sum(picked),0) AS picked,COALESCE(sum(quantity-released),0) AS allocated FROM wms_allocations WHERE tenant=t AND warehouse_id=w AND order_id=o) q;

-- ------------------------------------------------------------------
-- wms_track_count_review() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
BEGIN
 IF NEW.payload->'command'->>'type'='count_stock' THEN
  PERFORM wms_bump_resource(NEW.tenant,NEW.warehouse_id,jsonb_build_array('stock',
    NEW.payload->'command'->>'sku',NEW.payload->'command'->>'lot',NEW.payload->'command'->>'location'));
  PERFORM wms_bump_resource(NEW.tenant,NEW.warehouse_id,jsonb_build_array('inventory',NEW.payload->'command'->>'sku'));
 END IF;
 RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_track_resources() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
DECLARE r RECORD;
BEGIN
 IF TG_OP='UPDATE' AND NEW IS NOT DISTINCT FROM OLD THEN RETURN NULL; END IF;
 IF TG_OP='UPDATE' AND TG_TABLE_NAME='wms_orders' THEN
  IF (to_jsonb(NEW)-'data') IS NOT DISTINCT FROM (to_jsonb(OLD)-'data')
   AND (NEW.data-'lines'-'allocations') IS NOT DISTINCT FROM (OLD.data-'lines'-'allocations') THEN RETURN NULL; END IF;
 ELSIF TG_OP='UPDATE' AND TG_TABLE_NAME='wms_receipts' THEN
  IF (to_jsonb(NEW)-'data') IS NOT DISTINCT FROM (to_jsonb(OLD)-'data')
   AND (NEW.data-'lines'-'return_source') IS NOT DISTINCT FROM (OLD.data-'lines'-'return_source') THEN RETURN NULL; END IF;
 END IF;
 IF TG_OP='DELETE' THEN r=OLD; ELSE r=NEW; END IF;
 IF TG_TABLE_NAME='wms_stock' THEN
  PERFORM wms_bump_resource(r.tenant,r.warehouse_id,jsonb_build_array('stock',r.sku,r.lot,r.location));
  PERFORM wms_bump_resource(r.tenant,r.warehouse_id,jsonb_build_array('inventory',r.sku));
 ELSIF TG_TABLE_NAME='wms_products' THEN
  PERFORM wms_bump_resource(r.tenant,r.warehouse_id,jsonb_build_array('product',r.sku));
 ELSIF TG_TABLE_NAME='wms_locations' THEN
  PERFORM wms_bump_resource(r.tenant,r.warehouse_id,jsonb_build_array('location',r.code));
 ELSIF TG_TABLE_NAME IN('wms_orders','wms_receipts') THEN
  PERFORM wms_bump_resource(r.tenant,r.warehouse_id,jsonb_build_array(
    CASE WHEN TG_TABLE_NAME='wms_orders' THEN 'order' ELSE 'receipt' END,r.id));
 ELSIF TG_TABLE_NAME IN('wms_order_lines','wms_allocations') THEN
  PERFORM wms_bump_resource(r.tenant,r.warehouse_id,jsonb_build_array('order',r.order_id));
 ELSIF TG_TABLE_NAME IN('wms_receipt_lines','wms_return_lines') THEN
  PERFORM wms_bump_resource(r.tenant,r.warehouse_id,jsonb_build_array('receipt',r.receipt_id));
 ELSIF TG_TABLE_NAME='wms_exceptions' THEN
  IF r.order_id IS NOT NULL THEN
   PERFORM wms_bump_resource(r.tenant,r.warehouse_id,jsonb_build_array('order',r.order_id));
  END IF;
  IF TG_OP='UPDATE' AND OLD.order_id IS DISTINCT FROM NEW.order_id AND OLD.order_id IS NOT NULL THEN
   PERFORM wms_bump_resource(OLD.tenant,OLD.warehouse_id,jsonb_build_array('order',OLD.order_id));
  END IF;
 END IF;
 RETURN NULL;
END 

-- ------------------------------------------------------------------
-- wms_transfer_command_lines(d jsonb) RETURNS jsonb
-- LANGUAGE sql IMMUTABLE
 SELECT CASE WHEN jsonb_typeof(d)='array' THEN (SELECT jsonb_agg(jsonb_build_object('id',l->'id','sku',l->'sku','lot',l->'lot','location',l->'location','quantity',l->'quantity') ORDER BY l->>'id') FROM jsonb_array_elements(d) l) END;

-- ------------------------------------------------------------------
-- wms_transfer_commit_proof() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
DECLARE transfer TEXT;
BEGIN
 IF TG_TABLE_NAME='wms_transfers' THEN transfer=NEW.id; ELSE transfer=NEW.transfer_id; END IF;
 IF NOT wms_transfer_consistent(NEW.tenant,transfer) THEN RAISE EXCEPTION 'Transfer lacks exact original dispatch or arrival evidence' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END 

-- ------------------------------------------------------------------
-- wms_transfer_consistent(t text, transfer text) RETURNS boolean
-- LANGUAGE plpgsql STABLE
BEGIN
 IF NOT wms_transfer_original_consistent(t,transfer) THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM wms_transfer_loss_records r JOIN wms_transfers h ON h.tenant=r.tenant AND h.id=r.transfer_id
  LEFT JOIN wms_transfer_loss_records original ON original.tenant=r.tenant AND original.id=r.original_loss_id
  WHERE r.tenant=t AND r.transfer_id=transfer AND (
   r.warehouse_id<>h.destination_warehouse_id OR NOT wms_transfer_loss_original(r)
   OR (r.kind='reversal' AND (original.kind IS DISTINCT FROM 'loss'
    OR (r.transfer_id,r.line_id,r.warehouse_id) IS DISTINCT FROM (original.transfer_id,original.line_id,original.warehouse_id)
    OR r.version<=original.version))
   OR (r.kind='loss' AND (SELECT COALESCE(sum(x.quantity),0) FROM wms_transfer_loss_records x WHERE x.tenant=t AND x.original_loss_id=r.id)>r.quantity)
  )) THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM wms_transfer_lines l WHERE l.tenant=t AND l.transfer_id=transfer AND (
  wms_transfer_lost(t,transfer,l.id)<0 OR wms_transfer_lost(t,transfer,l.id)+
  (SELECT COALESCE(sum(m.quantity),0) FROM wms_movements m WHERE m.tenant=t AND m.transfer_id=transfer AND m.transfer_line_id=l.id AND m.kind='transfer_receive')>l.quantity
 )) THEN RETURN false; END IF;
 -- Retained events must not outlive a missing normalized original record.
 IF EXISTS(SELECT 1 FROM wms_events e WHERE e.tenant=t AND e.payload#>>'{transfer_loss_record,transfer_id}'=transfer
 AND (e.payload->>'type' IN('transfer.loss_recorded','transfer.loss_reversed')
   OR e.payload#>>'{command,type}' IN('record_transfer_loss','reverse_transfer_loss'))
 AND NOT EXISTS(SELECT 1 FROM wms_transfer_loss_records r WHERE r.tenant=t AND r.transfer_id=transfer AND r.event_id=e.id)) THEN RETURN false; END IF;
 RETURN true;
END 

-- ------------------------------------------------------------------
-- wms_transfer_document(t text, transfer text) RETURNS jsonb
-- LANGUAGE sql STABLE
 SELECT to_jsonb(h)-'tenant'||jsonb_build_object('lines',(
  SELECT jsonb_agg(to_jsonb(l)-'tenant'-'transfer_id'-'source_warehouse_id'-'destination_warehouse_id'||jsonb_build_object(
   'received',(SELECT COALESCE(sum(m.quantity),0)::bigint FROM wms_movements m WHERE m.tenant=t AND m.transfer_id=transfer AND m.transfer_line_id=l.id AND m.kind='transfer_receive'),
   'lost',wms_transfer_lost(t,transfer,l.id),'loss_record_count',(SELECT count(*) FROM wms_transfer_loss_records r WHERE r.tenant=t AND r.transfer_id=transfer AND r.line_id=l.id)) ORDER BY l.id)
  FROM wms_transfer_lines l WHERE l.tenant=t AND l.transfer_id=transfer))
 FROM wms_transfers h WHERE h.tenant=t AND h.id=transfer;

-- ------------------------------------------------------------------
-- wms_transfer_lock() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
DECLARE w TEXT;
BEGIN
 IF TG_TABLE_NAME='wms_transfers' THEN
  FOR w IN SELECT x FROM unnest(ARRAY[NEW.source_warehouse_id,NEW.destination_warehouse_id]) x ORDER BY x LOOP
   PERFORM wms_serialize_shipment(NEW.tenant,w);
  END LOOP;
 ELSE
  PERFORM wms_serialize_shipment(NEW.tenant,NEW.warehouse_id);
 END IF;
 RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_transfer_loss_lock() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
BEGIN PERFORM wms_serialize_shipment(NEW.tenant,NEW.warehouse_id); RETURN NEW; END 

-- ------------------------------------------------------------------
-- wms_transfer_loss_original(r wms_transfer_loss_records) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT EXISTS(SELECT 1 FROM wms_events e JOIN wms_commands c
 ON c.tenant=e.tenant AND c.warehouse_id=e.warehouse_id AND c.request_id=e.payload->>'request_id'
 WHERE e.id=r.event_id AND e.tenant=r.tenant AND e.warehouse_id=r.warehouse_id AND e.version=r.version
 AND r.version<=(SELECT version FROM wms_warehouses WHERE tenant=r.tenant AND warehouse_id=r.warehouse_id)
 AND e.payload->>'id'=e.id AND e.payload->>'tenant'=r.tenant AND e.payload->>'warehouse_id'=r.warehouse_id
 AND e.payload->'version'=to_jsonb(r.version) AND e.payload->>'actor'=r.actor AND c.actor=r.actor
 AND e.payload->>'occurred_at'=r.recorded_at AND e.payload->'result'=c.result
 AND c.result=jsonb_build_object('entity_id',r.id,'version',r.version,'type',CASE r.kind WHEN 'loss' THEN 'transfer.loss_recorded' ELSE 'transfer.loss_reversed' END)
 AND e.payload->>'type'=c.result->>'type'
 AND e.payload->'transfer_loss_record'=to_jsonb(r)-'tenant'
 AND e.payload->'command'=CASE r.kind WHEN 'loss' THEN
  jsonb_build_object('type','record_transfer_loss','transfer_id',r.transfer_id,'line_id',r.line_id,'quantity',r.quantity,'incident_reference',r.incident_reference,'reason',r.reason)
 ELSE jsonb_build_object('type','reverse_transfer_loss','loss_id',r.original_loss_id,'quantity',r.quantity,'reason',r.reason) END);

-- ------------------------------------------------------------------
-- wms_transfer_lost(t text, transfer text, line text) RETURNS bigint
-- LANGUAGE sql STABLE
 SELECT COALESCE(sum(CASE WHEN kind='loss' THEN quantity ELSE -quantity END),0)::bigint
 FROM wms_transfer_loss_records WHERE tenant=t AND transfer_id=transfer AND line_id=line;

-- ------------------------------------------------------------------
-- wms_transfer_open(t text, transfer text) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT EXISTS(SELECT 1 FROM wms_transfer_lines l WHERE l.tenant=t AND l.transfer_id=transfer AND l.quantity>wms_transfer_lost(t,transfer,l.id)+
  (SELECT COALESCE(sum(m.quantity),0) FROM wms_movements m WHERE m.tenant=t AND m.transfer_id=transfer AND m.transfer_line_id=l.id AND m.kind='transfer_receive'));

-- ------------------------------------------------------------------
-- wms_transfer_original_consistent(t text, transfer text) RETURNS boolean
-- LANGUAGE plpgsql STABLE
DECLARE h RECORD; source JSONB; expected JSONB;
BEGIN
 SELECT * INTO h FROM wms_transfers WHERE tenant=t AND id=transfer;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT payload INTO source FROM wms_events WHERE id=h.source_event_id AND tenant=t AND warehouse_id=h.source_warehouse_id AND version=h.source_version;
 IF NOT FOUND OR source->>'type' IS DISTINCT FROM 'transfer.dispatched'
 OR source->>'id' IS DISTINCT FROM h.source_event_id OR source->>'tenant' IS DISTINCT FROM t
 OR source->>'warehouse_id' IS DISTINCT FROM h.source_warehouse_id OR source->'version' IS DISTINCT FROM to_jsonb(h.source_version)
 OR source->>'actor' IS DISTINCT FROM h.actor OR source#>>'{command,type}' IS DISTINCT FROM 'dispatch_transfer'
 OR source#>>'{command,reference}' IS DISTINCT FROM h.reference
 OR source#>>'{command,destination_warehouse_id}' IS DISTINCT FROM h.destination_warehouse_id
 OR source#>>'{command,carrier}' IS DISTINCT FROM h.carrier OR source#>>'{command,handoff_reference}' IS DISTINCT FROM h.handoff_reference
 OR source#>>'{result,type}' IS DISTINCT FROM 'transfer.dispatched' OR source#>>'{result,entity_id}' IS DISTINCT FROM transfer OR source#>'{result,version}' IS DISTINCT FROM to_jsonb(h.source_version)
 OR h.source_version>(SELECT version FROM wms_warehouses WHERE tenant=t AND warehouse_id=h.source_warehouse_id) THEN RETURN false; END IF;
 SELECT jsonb_agg(jsonb_build_object('id',l.id,'sku',l.sku,'lot',l.lot,'location',l.location,'quantity',l.quantity) ORDER BY l.id) INTO expected FROM wms_transfer_lines l WHERE l.tenant=t AND l.transfer_id=transfer;
 IF expected IS NULL OR jsonb_array_length(expected)>100 OR expected IS DISTINCT FROM wms_transfer_command_lines(source#>'{command,lines}') THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM wms_transfer_lines l LEFT JOIN wms_movements m ON m.id=l.movement_id
  WHERE l.tenant=t AND l.transfer_id=transfer AND
  (m.id IS NULL OR (m.tenant,m.warehouse_id,m.transfer_id,m.transfer_line_id,m.transfer_event_id,m.kind,m.sku,m.lot,m.from_location,m.quantity,m.reference)
    IS DISTINCT FROM (t,h.source_warehouse_id,transfer,l.id,h.source_event_id,'transfer_dispatch',l.sku,l.lot,l.location,l.quantity,transfer)
   OR m.to_location IS NOT NULL OR m.data->>'actor' IS DISTINCT FROM h.actor OR m.data->>'reason' IS DISTINCT FROM h.handoff_reference
   OR (SELECT kind FROM wms_locations WHERE tenant=t AND warehouse_id=h.source_warehouse_id AND code=l.location) IS DISTINCT FROM 'storage'
   OR (SELECT COALESCE(sum(quantity),0) FROM wms_movements WHERE tenant=t AND transfer_id=transfer AND transfer_line_id=l.id AND kind='transfer_receive')>l.quantity)) THEN RETURN false; END IF;
 IF EXISTS(SELECT 1 FROM wms_movements m JOIN wms_transfer_lines l ON l.tenant=m.tenant AND l.transfer_id=m.transfer_id AND l.id=m.transfer_line_id
  LEFT JOIN wms_events e ON e.id=m.transfer_event_id
  WHERE m.tenant=t AND m.transfer_id=transfer AND (
   (m.kind='transfer_dispatch' AND m.id<>l.movement_id) OR
   (m.kind='transfer_receive' AND (
    m.warehouse_id<>h.destination_warehouse_id OR m.sku<>l.sku OR m.lot<>l.lot OR m.from_location IS NOT NULL OR m.to_location IS NULL OR m.reference<>transfer
    OR (SELECT kind FROM wms_locations WHERE tenant=t AND warehouse_id=m.warehouse_id AND code=m.to_location) IS DISTINCT FROM 'receiving'
    OR e.tenant IS DISTINCT FROM t OR e.warehouse_id IS DISTINCT FROM h.destination_warehouse_id OR e.version<=0
    OR e.version>(SELECT version FROM wms_warehouses WHERE tenant=t AND warehouse_id=h.destination_warehouse_id)
    OR e.payload->>'type' IS DISTINCT FROM 'transfer.received' OR e.payload->>'id' IS DISTINCT FROM e.id
    OR e.payload->>'tenant' IS DISTINCT FROM t OR e.payload->>'warehouse_id' IS DISTINCT FROM h.destination_warehouse_id
    OR e.payload->'version' IS DISTINCT FROM to_jsonb(e.version) OR e.payload->>'actor' IS DISTINCT FROM m.data->>'actor'
    OR e.payload#>>'{command,type}' IS DISTINCT FROM 'receive_transfer' OR e.payload#>>'{command,transfer_id}' IS DISTINCT FROM transfer
    OR e.payload#>>'{command,line_id}' IS DISTINCT FROM l.id OR e.payload#>'{command,quantity}' IS DISTINCT FROM to_jsonb(m.quantity)
    OR e.payload#>>'{command,location}' IS DISTINCT FROM m.to_location OR e.payload#>>'{command,arrival_reference}' IS DISTINCT FROM m.data->>'reason'
    OR COALESCE(length(btrim(m.data->>'reason')),0)=0
    OR e.payload#>>'{result,type}' IS DISTINCT FROM 'transfer.received' OR e.payload#>>'{result,entity_id}' IS DISTINCT FROM transfer OR e.payload#>'{result,version}' IS DISTINCT FROM to_jsonb(e.version)
   )))) THEN RETURN false; END IF;
 RETURN true;
END 

-- ------------------------------------------------------------------
-- wms_unit_commit_proof() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
DECLARE eid TEXT;
BEGIN
 IF TG_TABLE_NAME='wms_unit_pack_changes' THEN
  eid=NEW.source_event_id;
  IF EXISTS(SELECT 1 FROM (SELECT DISTINCT ON(code) code,enabled FROM wms_unit_pack_changes WHERE tenant=NEW.tenant AND warehouse_id=NEW.warehouse_id AND sku=NEW.sku AND version<=NEW.version ORDER BY code,version DESC) p WHERE enabled HAVING count(*)>20) THEN
   RAISE EXCEPTION 'A product cannot enable more than twenty packaging units' USING ERRCODE='23514';
  END IF;
 ELSIF TG_TABLE_NAME='wms_events' THEN eid=NEW.id; ELSE eid=NEW.event_id; END IF;
 IF NOT wms_unit_event_valid(NEW.tenant,NEW.warehouse_id,eid) THEN RAISE EXCEPTION 'Unit observation or pack definition lacks its exact original conversion source' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END 

-- ------------------------------------------------------------------
-- wms_unit_event_valid(t text, w text, eid text) RETURNS boolean
-- LANGUAGE plpgsql STABLE
DECLARE e RECORD; inputs JSONB; actual BIGINT;
BEGIN
 SELECT * INTO e FROM wms_events WHERE tenant=t AND warehouse_id=w AND id=eid;
 IF NOT FOUND THEN RETURN false; END IF;
 inputs=COALESCE(e.payload->'unit_inputs','[]'::jsonb);
 IF jsonb_typeof(inputs)<>'array' OR jsonb_array_length(inputs)>100 THEN RETURN false; END IF;
 SELECT count(*) INTO actual FROM wms_unit_observations WHERE tenant=t AND warehouse_id=w AND event_id=eid;
 IF actual<>jsonb_array_length(inputs) OR EXISTS(SELECT 1 FROM wms_unit_observations r WHERE r.tenant=t AND r.warehouse_id=w AND r.event_id=eid AND NOT wms_unit_observation_original(r)) THEN RETURN false; END IF;
 IF e.payload#>>'{command,type}'='set_unit_pack' THEN
  IF NOT EXISTS(SELECT 1 FROM wms_unit_pack_changes p WHERE p.tenant=t AND p.warehouse_id=w AND p.source_event_id=eid AND wms_unit_pack_original(p)) THEN RETURN false; END IF;
 ELSIF e.payload?'unit_pack_change' OR EXISTS(SELECT 1 FROM wms_unit_pack_changes p WHERE p.tenant=t AND p.warehouse_id=w AND p.source_event_id=eid) THEN RETURN false;
 END IF;
 RETURN true;
END 

-- ------------------------------------------------------------------
-- wms_unit_lock() RETURNS trigger
-- LANGUAGE plpgsql VOLATILE
BEGIN
 PERFORM wms_serialize_shipment(NEW.tenant,NEW.warehouse_id);
 IF TG_TABLE_NAME='wms_unit_pack_changes' THEN PERFORM wms_bump_resource(NEW.tenant,NEW.warehouse_id,jsonb_build_array('product',NEW.sku)); END IF;
 RETURN NEW;
END 

-- ------------------------------------------------------------------
-- wms_unit_observation_original(r wms_unit_observations) RETURNS boolean
-- LANGUAGE plpgsql STABLE
BEGIN
 RETURN EXISTS(SELECT 1 FROM wms_events e JOIN wms_commands c ON c.tenant=e.tenant AND c.warehouse_id=e.warehouse_id AND c.request_id=e.payload->>'request_id'
 JOIN wms_unit_pack_changes p ON p.tenant=r.tenant AND p.warehouse_id=r.warehouse_id AND p.id=r.definition_id
 WHERE e.id=r.event_id AND e.tenant=r.tenant AND e.warehouse_id=r.warehouse_id AND e.version=r.version
 AND e.payload->>'id'=e.id AND e.payload->>'tenant'=r.tenant AND e.payload->>'warehouse_id'=r.warehouse_id
 AND e.payload->'version'=to_jsonb(r.version) AND e.payload->>'actor'=c.actor AND e.payload->'result'=c.result
 AND c.result->'version'=to_jsonb(r.version) AND c.result->>'type'=e.payload->>'type'
 AND r.version<=(SELECT version FROM wms_warehouses WHERE tenant=r.tenant AND warehouse_id=r.warehouse_id)
 AND p.sku=r.sku AND p.code=r.pack_code AND p.each_per_pack=r.each_per_pack AND p.enabled AND wms_unit_pack_original(p)
 AND r.each_quantity=r.pack_quantity*p.each_per_pack
 AND p.id=(SELECT id FROM wms_unit_pack_changes x WHERE x.tenant=r.tenant AND x.warehouse_id=r.warehouse_id AND x.sku=r.sku AND x.code=r.pack_code AND x.version<r.version ORDER BY x.version DESC LIMIT 1)
 AND e.payload->'unit_inputs'->(r.ordinal-1)=jsonb_build_object('target',r.target,'sku',r.sku,'pack_code',r.pack_code,'definition_id',r.definition_id,'pack_quantity',r.pack_quantity,'each_per_pack',r.each_per_pack)
 AND EXISTS(SELECT 1 FROM wms_unit_targets(r.tenant,r.warehouse_id,e.payload->'command') q
 WHERE q.target=r.target AND q.sku=r.sku AND q.each_quantity=r.each_quantity AND (q.each_quantity>0 OR q.allow_zero)));
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END 

-- ------------------------------------------------------------------
-- wms_unit_pack_original(p wms_unit_pack_changes) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT EXISTS(SELECT 1 FROM wms_events e JOIN wms_commands c ON c.tenant=e.tenant AND c.warehouse_id=e.warehouse_id AND c.request_id=e.payload->>'request_id'
 WHERE e.id=p.source_event_id AND e.tenant=p.tenant AND e.warehouse_id=p.warehouse_id AND e.version=p.version
 AND e.payload->>'id'=e.id AND e.payload->>'tenant'=p.tenant AND e.payload->>'warehouse_id'=p.warehouse_id
 AND e.payload->'version'=to_jsonb(p.version) AND e.payload->>'actor'=p.actor AND c.actor=p.actor
 AND p.version<=(SELECT version FROM wms_warehouses WHERE tenant=p.tenant AND warehouse_id=p.warehouse_id)
 AND (p.enabled OR COALESCE((SELECT x.enabled FROM wms_unit_pack_changes x WHERE x.tenant=p.tenant AND x.warehouse_id=p.warehouse_id AND x.sku=p.sku AND x.code=p.code AND x.version<p.version ORDER BY x.version DESC LIMIT 1),false))
 AND e.payload->>'type'='inventory.unit_pack_changed' AND e.payload->>'occurred_at'=p.recorded_at
 AND e.payload->'unit_pack_change'=to_jsonb(p)-'tenant'
 AND e.payload->'result'=c.result AND c.result=jsonb_build_object('entity_id',p.id,'version',p.version,'type','inventory.unit_pack_changed')
 AND e.payload->'command'=jsonb_build_object('type','set_unit_pack','sku',p.sku,'code',p.code,'label',p.label,'each_per_pack',p.each_per_pack,'enabled',p.enabled,'reason',p.reason));

-- ------------------------------------------------------------------
-- wms_unit_scope_valid(t text, w text) RETURNS boolean
-- LANGUAGE sql STABLE
 SELECT NOT EXISTS(SELECT 1 FROM wms_unit_pack_changes p WHERE p.tenant=t AND p.warehouse_id=w AND
  (p.version>(SELECT version FROM wms_warehouses WHERE tenant=t AND warehouse_id=w) OR NOT wms_unit_pack_original(p)))
 AND NOT EXISTS(SELECT 1 FROM (SELECT DISTINCT ON(sku,code) sku,code,enabled FROM wms_unit_pack_changes WHERE tenant=t AND warehouse_id=w ORDER BY sku,code,version DESC) p WHERE enabled GROUP BY sku HAVING count(*)>20)
 AND NOT EXISTS(SELECT 1 FROM wms_events e WHERE e.tenant=t AND e.warehouse_id=w AND
  (e.payload?'unit_inputs' OR e.payload?'unit_pack_change' OR e.payload#>>'{command,type}'='set_unit_pack' OR e.payload#>>'{result,type}'='inventory.unit_pack_changed') AND NOT wms_unit_event_valid(t,w,e.id))
 AND NOT EXISTS(SELECT 1 FROM wms_unit_observations r WHERE r.tenant=t AND r.warehouse_id=w AND NOT wms_unit_observation_original(r));

-- ------------------------------------------------------------------
-- wms_unit_targets(t text, w text, d jsonb) RETURNS TABLE(target jsonb, sku text, each_quantity bigint, allow_zero boolean)
-- LANGUAGE sql STABLE
 SELECT '[]'::jsonb,d->>'sku',(d->>'quantity')::bigint,false WHERE d->>'type'='move_stock'
 UNION ALL SELECT '[]'::jsonb,d->>'sku',(d->>'counted')::bigint,true WHERE d->>'type'='count_stock'
 UNION ALL SELECT '[]'::jsonb,l.sku,(d->>'quantity')::bigint,false FROM wms_receipt_lines l
 WHERE d->>'type'='receive' AND l.tenant=t AND l.warehouse_id=w AND l.receipt_id=d->>'receipt_id' AND l.id=d->>'line_id'
 UNION ALL SELECT '[]'::jsonb,l.sku,(d->>'quantity')::bigint,false FROM wms_order_lines l
 WHERE d->>'type' IN('pick','unpick') AND l.tenant=t AND l.warehouse_id=w AND l.order_id=d->>'order_id' AND l.id=d->>'line_id'
 UNION ALL SELECT '[]'::jsonb,l.sku,(d->>'quantity')::bigint,false FROM wms_transfer_lines l
 WHERE d->>'type' IN('receive_transfer','record_transfer_loss') AND l.tenant=t AND l.destination_warehouse_id=w AND l.transfer_id=d->>'transfer_id' AND l.id=d->>'line_id'
 UNION ALL SELECT '[]'::jsonb,l.sku,(d->>'quantity')::bigint,false FROM wms_transfer_loss_records r
 JOIN wms_transfer_lines l ON l.tenant=r.tenant AND l.transfer_id=r.transfer_id AND l.id=r.line_id
 WHERE d->>'type'='reverse_transfer_loss' AND r.tenant=t AND r.warehouse_id=w AND r.id=d->>'loss_id' AND r.kind='loss'
 UNION ALL SELECT jsonb_build_array(l->>'id'),l->>'sku',(l->>'quantity')::bigint,false
 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(d->'lines')='array' THEN d->'lines' ELSE '[]'::jsonb END) l
 WHERE d->>'type' IN('dispatch_transfer','create_order','create_receipt')
 UNION ALL SELECT jsonb_build_array(l->>'id'),o.sku,(l->>'quantity')::bigint,false
 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(d->'lines')='array' THEN d->'lines' ELSE '[]'::jsonb END) l
 JOIN wms_order_lines o ON o.tenant=t AND o.warehouse_id=w AND o.order_id=d->>'order_id' AND o.id=l->>'order_line_id'
 WHERE d->>'type'='create_return'
 UNION ALL SELECT jsonb_build_array(l->>'line_id',l->>'location',l->>'lot'),o.sku,(l->>'quantity')::bigint,false
 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(d->'lines')='array' THEN d->'lines' ELSE '[]'::jsonb END) l
 JOIN wms_order_lines o ON o.tenant=t AND o.warehouse_id=w AND o.order_id=d->>'order_id' AND o.id=l->>'line_id'
 WHERE d->>'type'='pack_shipment';

-- ------------------------------------------------------------------
-- wms_valid_balances(document jsonb) RETURNS boolean
-- LANGUAGE sql IMMUTABLE
    SELECT CASE WHEN jsonb_typeof(document->'stocks') IS DISTINCT FROM 'array' THEN false ELSE
      NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(document->'stocks') AS b
        WHERE NOT COALESCE(
          jsonb_typeof(b->'on_hand') = 'number' AND jsonb_typeof(b->'reserved') = 'number'
          AND (b->>'on_hand')::numeric = trunc((b->>'on_hand')::numeric)
          AND (b->>'reserved')::numeric = trunc((b->>'reserved')::numeric)
          AND (b->>'on_hand')::numeric BETWEEN 0 AND 1000000000
          AND (b->>'reserved')::numeric BETWEEN 0 AND (b->>'on_hand')::numeric,
          false
        )
      ) AND (
        SELECT count(*) = count(DISTINCT jsonb_build_array(b->'sku', b->'lot', b->'location'))
        FROM jsonb_array_elements(document->'stocks') AS b
      )
    END;

